const DICTS: Record<Lang, Dict> = { 'zh-TW': zhTW, en, 'zh-Hans': zhHans };
export const LANGS: Lang[] = ['zh-TW', 'en', 'zh-Hans'];
export const LANG_LABEL: Record<Lang, string> = { 'zh-TW': '繁', en: 'EN', 'zh-Hans': '简' };

/** Map the arcade's locale codes (zh-TW / en / zh-CN, plus URL aliases) onto this game's. */
export function normalizeLang(code: string | null | undefined): Lang | null {
  if (!code) return null;
  const c = code.toLowerCase().replace('_', '-');
  if (c === 'en' || c.startsWith('en-')) return 'en';
  if (c === 'zh-cn' || c === 'zh-hans' || c === 'zh-sg' || c === 'zh-my') return 'zh-Hans';
  if (c === 'zh' || c === 'zh-tw' || c === 'zh-hant' || c === 'zh-hk' || c === 'zh-mo')
    return 'zh-TW';
  return null;
}

/**
 * Pick the starting language. `explicit` holds choices the player made on purpose, in order of
 * priority (?lang= in the URL, this game's saved choice, the arcade lobby's saved choice).
 * Without one, every Chinese browser locale (incl. zh-CN) starts in Traditional Chinese;
 * Simplified is only picked via the language button.
 */
export function detectLang(
  explicit: (string | null | undefined)[],
  navLang: string = typeof navigator === 'undefined' ? '' : navigator.language,
): Lang {
  for (const c of explicit) {
    const l = normalizeLang(c);
    if (l) return l;
  }
  const nav = (navLang || '').toLowerCase();
  return nav && !nav.startsWith('zh') ? 'en' : 'zh-TW';
}

/** The arcade lobby's locale code for one of this game's languages. */
export function arcadeLocale(lang: Lang): 'zh-TW' | 'en' | 'zh-CN' {
  return lang === 'zh-Hans' ? 'zh-CN' : lang;
}

export function dict(lang: Lang): Dict {
  return DICTS[lang];
}

export function fmt(s: string, vars: Record<string, string | number>): string {
  return s.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? ''));
}
