const NECK_PARTS = new Set([0, 1, 2, 3, 4, 6, 7, 16]); // neck fills + the big outline (indices into SNEK_PARTS)

function mix(a: string, b: string, t: number) {
  const pa = parseInt(a.slice(1), 16);
  const pb = parseInt(b.slice(1), 16);
  const ch = (s: number) => Math.round(((pa >> s) & 255) * (1 - t) + ((pb >> s) & 255) * t);
  return `#${((1 << 24) | (ch(16) << 16) | (ch(8) << 8) | ch(0)).toString(16).slice(1)}`;
}

function fillFor(cls: string, s: HeadStyle) {
  switch (cls) {
    case 'st11': // head + right side of the neck
    case 'st9': // eyelids + left side of the neck
      return s.mid;
    case 'st12':
    case 'st10':
      return mix(s.mid, s.top, 0.3);
    case 'st2': // crest
      return s.top;
    case 'st0': // neck front
    case 'st5': // jaw
      return s.chin;
    case 'st7': // neck highlight
      return mix(s.chin, '#ffffff', 0.45);
    case 'st4': // eyes
      return '#f94b60';
    case 'st6':
      return '#ffffff';
    default: // st1 / st8 lines
      return INK;
  }
}

function closedEyes(s: HeadStyle) {
  const lid = (e: typeof EYE_L) =>
    `<ellipse cx="${e.x}" cy="${e.y}" rx="${e.rx - 32}" ry="${e.ry - 32}" fill="${s.mid}"/>
     <path d="M${e.x - e.rx * 0.72},${e.y + e.ry * 0.12} Q${e.x},${e.y + e.ry * 0.62} ${e.x + e.rx * 0.72},${e.y + e.ry * 0.12}" fill="none" stroke="${INK}" stroke-width="40" stroke-linecap="round"/>`;
  return lid(EYE_L) + lid(EYE_R);
}

/**
 * The in-game tongue is a separate animated part (stem + fork, each as an outline layer and a fill layer),
 * so it can slide out of the mouth and flicker instead of popping in as a whole new image.
 * Local space: the tongue points along +x from its root; units are logo units.
 */
export const TONGUE = (() => {
  const L = 330; // stem length
  const O = 36; // half of the outline width = padding
  const P = 125; // prong length
  const A = (24 * Math.PI) / 180; // half-angle between the prongs
  const px = Math.round(P * Math.cos(A));
  const py = Math.round(P * Math.sin(A));
  const svg = (w: number, h: number, body: string) =>
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}"><g fill="none" stroke-linecap="round" stroke-linejoin="round">${body}</g></svg>`;
  const sw = L + O * 2;
  const sh = O * 2;
  const stemD = `M${O},${O} L${O + L},${O}`;
  const fw = px + O * 2;
  const fh = (py + O) * 2;
  const forkD = `M${O},${fh / 2} L${O + px},${fh / 2 - py} M${O},${fh / 2} L${O + px},${fh / 2 + py}`;
  return {
    /** root of the tongue in logo units (front corner of the mouth) */
    anchor: [830, 1478] as [number, number],
    /** direction in world space (y up): out of the mouth, slightly downward */
    angle: Math.atan2(-58, -180),
    len: L,
    pad: O,
    stem: {
      w: sw,
      h: sh,
      ink: svg(sw, sh, `<path d="${stemD}" stroke="${INK}" stroke-width="${O * 2}"/>`),
      fill: svg(
        sw,
        sh,
        `<path d="${stemD}" stroke="#ff3d6e" stroke-width="38"/><path d="M${O + 20},${O - 6} L${O + L * 0.55},${O - 6}" stroke="#ff9db5" stroke-width="10"/>`,
      ),
    },
    fork: {
      w: fw,
      h: fh,
      ink: svg(fw, fh, `<path d="${forkD}" stroke="${INK}" stroke-width="${O * 2 - 8}"/>`),
      fill: svg(fw, fh, `<path d="${forkD}" stroke="#ff3d6e" stroke-width="32"/>`),
    },
  };
})();

/** the head image covers this square of logo units */
export const HEAD_VIEW = VB;

export function headSvg(s: HeadStyle, opts: { closed?: boolean } = {}): string {
  const id = s.id;
  const a = ACCESSORIES[s.acc]();
  const gold = id === 'snek';
  const parts = SNEK_PARTS.map((p) => `<path d="${p.d}" fill="${fillFor(p.cls, s)}"/>`).join('');
  const neckClip = SNEK_PARTS.filter((_, i) => NECK_PARTS.has(i))
    .map((p) => `<path d="${p.d}"/>`)
    .join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${VB.x} ${VB.y} ${VB.s} ${VB.s}" width="512" height="512">
<defs>
  <clipPath id="cut-${id}"><path d="M0,0 H3000 V2236 L2100,2236 Q1400,2342 700,2236 L0,2236 Z"/></clipPath>
  <clipPath id="neck-${id}">${neckClip}</clipPath>
  ${a.defs ?? ''}
</defs>
${a.back ?? ''}
<g clip-path="url(#cut-${id})">${parts}</g>
<path d="${CUT}" fill="none" stroke="${INK}" stroke-width="46" clip-path="url(#neck-${id})"/>
${gold ? `<ellipse cx="1180" cy="860" rx="230" ry="60" transform="rotate(-18 1180 860)" fill="#fff" opacity=".45"/><ellipse cx="2160" cy="980" rx="90" ry="30" transform="rotate(20 2160 980)" fill="#fff" opacity=".4"/><ellipse cx="1300" cy="2120" rx="70" ry="160" transform="rotate(-20 1300 2120)" fill="#fff" opacity=".25"/>` : ''}
${s.blush ? `<ellipse cx="770" cy="1580" rx="110" ry="48" fill="#ff6f96" opacity=".45"/><ellipse cx="2215" cy="1600" rx="80" ry="38" fill="#ff6f96" opacity=".45"/>` : ''}
${opts.closed ? closedEyes(s) : ''}
${a.front ?? ''}
</svg>`;
}

// ------------------------------------------------------------------ accessories
// Some accessories are drawn in a 512-unit design space (from the earlier head sheet) and placed
// onto the logo with place(); the eye-bound ones are drawn directly in logo units.
interface AccSvg {
  defs?: string;
  back?: string;
  front?: string;
}
type Place = { from: [number, number]; to: [number, number]; s: number; rot?: number };
const T = (p: Place) =>
  `translate(${p.to[0]} ${p.to[1]}) rotate(${p.rot ?? 0}) scale(${p.s}) translate(${-p.from[0]} ${-p.from[1]})`;
const place = (p: Place, svg: string) => `<g transform="${T(p)}">${svg}</g>`;
/** map a design-space point through a placement (for collision shapes) */
function mapPt(p: Place, [x, y]: [number, number]): [number, number] {
  const a = ((p.rot ?? 0) * Math.PI) / 180;
  const dx = (x - p.from[0]) * p.s;
  const dy = (y - p.from[1]) * p.s;
  return [
    p.to[0] + dx * Math.cos(a) - dy * Math.sin(a),
    p.to[1] + dx * Math.sin(a) + dy * Math.cos(a),
  ];
}

const ink = (w = 8) =>
  `stroke="${INK}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"`;

function sparkle(x: number, y: number, r: number, color = '#fff') {
  return `<path d="M${x},${y - r} Q${x + r * 0.18},${y - r * 0.18} ${x + r},${y} Q${x + r * 0.18},${y + r * 0.18} ${x},${y + r} Q${x - r * 0.18},${y + r * 0.18} ${x - r},${y} Q${x - r * 0.18},${y - r * 0.18} ${x},${y - r} Z" fill="${color}"/>`;
}

function flame(cx: number, base: number, w: number, h: number) {
  const p = (k: number, ww: number, hh: number) =>
    `M${cx - ww / 2},${base} C${cx - ww / 2},${base - hh * 0.45} ${cx - ww * 0.05},${base - hh * 0.55} ${cx + ww * 0.05 * k},${base - hh} C${cx + ww * 0.25},${base - hh * 0.6} ${cx + ww / 2},${base - hh * 0.45} ${cx + ww / 2},${base} Z`;
  return `<path d="${p(1, w, h)}" fill="url(#fireO)" ${ink(8)}/>
  <path d="${p(-1, w * 0.55, h * 0.62)}" fill="url(#fireI)"/>`;
}

