// ------------------------------------------------------------------ collision shapes
// Returned in the 512-unit output space (image centre = 256,256). Convex pieces only.
export type HeadShape = { circle: [number, number, number] } | { poly: [number, number][] };

const to512 = ([x, y]: [number, number]): [number, number] => [(x - VB.x) * K, (y - VB.y) * K];
const poly = (pts: [number, number][]): HeadShape => ({ poly: pts.map(to512) });
const placedPoly = (p: Place, pts: [number, number][]): HeadShape =>
  poly(pts.map((q) => mapPt(p, q)));
const placedCircle = (p: Place, [x, y, r]: [number, number, number]): HeadShape => {
  const [cx, cy] = to512(mapPt(p, [x, y]));
  return { circle: [cx, cy, r * p.s * K] };
};
const halfEllipse = (cx: number, cy: number, rx: number, ry: number, n = 10): [number, number][] =>
  Array.from({ length: n + 1 }, (_, i) => {
    const a = Math.PI + (i / n) * Math.PI;
    return [cx + Math.cos(a) * rx, cy + Math.sin(a) * ry] as [number, number];
  });
const rect = (x0: number, y0: number, x1: number, y1: number): [number, number][] => [
  [x0, y0],
  [x1, y0],
  [x1, y1],
  [x0, y1],
];

