// Live SNEK market data from GeckoTerminal (CoinGecko's on-chain DEX data; CORS enabled, no key).
// Source: the main SNEK/ADA pool on Minswap (deepest liquidity).
// - 24h of 15-minute candles, refreshed every minute; quiet periods with no trades are filled
//   with flat candles at the previous close, exactly like an exchange chart
// - pool price + 24h change polled every 5 s; the newest candle is updated with it
// - everything is cached in localStorage; offline / rate-limited -> last known data, never a crash
// Nothing here invents prices: if there is no data at all the chart shows a clearly labelled demo.

export interface Candle {
  t: number; // candle start, ms
  o: number;
  h: number;
  l: number;
  c: number;
}

export type MarketStatus = 'loading' | 'live' | 'offline' | 'demo';

// Point VITE_MARKET_API at your own caching proxy in production (same paths as GeckoTerminal v2)
// so every player shares one upstream request instead of each using up the per-IP rate limit.
const PROXY = (import.meta as unknown as { env?: Record<string, string | undefined> }).env
  ?.VITE_MARKET_API;
const API = PROXY || 'https://api.geckoterminal.com/api/v2';
/** SNEK/ADA on Minswap — the deepest SNEK pool (~$700k liquidity) */
const POOL =
  'f5808c2c990d86da54bfc97d89cee6efa20cd8461616359478d96b4c2ffadbb87144e875749122e0bbb9f535eeaa7f5660c6c4a91bcc4121e477f08d';
export const PERIOD_MIN = 15;
const PERIOD = PERIOD_MIN * 60 * 1000;
// Keyless GeckoTerminal starts answering 429 after a handful of calls per minute per IP, so a browser
// talking to it directly polls gently; behind our own caching proxy every player can poll every 5 s.
const PRICE_EVERY = PROXY ? 5_000 : 20_000;
const OHLC_EVERY = 60_000;
const CACHE_KEY = 'snek-merge:market-gt15';
const MAX_CANDLES = 96; // 24 hours of 15-minute candles

export class Market {
  candles: Candle[] = [];
  price: number | null = null;
  change24h: number | null = null;
  updatedAt = 0;
  /** when the price was last confirmed by the source (even if unchanged) */
  checkedAt = 0;
  status: MarketStatus = 'loading';
  /** bumps on every data change so views know when to redraw */
  version = 0;
  /** true once we hold real candles (fresh or cached), so demo data is never called "offline" */
  private real = false;

  private priceTimer = 0;
  private ohlcTimer = 0;
  private backoff = 1;
  private stopped = false;

  constructor() {
    this.loadCache();
  }

  start() {
    void this.refreshOhlc().then(() => this.refreshPrice());
    document.addEventListener('visibilitychange', () => {
      // catch up right away when the tab comes back
      if (!document.hidden) {
        void this.refreshPrice();
        if (Date.now() - this.updatedAt > OHLC_EVERY) void this.refreshOhlc();
      }
    });
  }

  stop() {
    this.stopped = true;
    clearTimeout(this.priceTimer);
    clearTimeout(this.ohlcTimer);
  }

  // ---------------------------------------------------------------- fetching
  private async get<T>(path: string): Promise<T> {
    const ctrl = new AbortController();
    const to = setTimeout(() => ctrl.abort(), 12_000);
    try {
      const r = await fetch(`${API}${path}`, {
        signal: ctrl.signal,
        cache: 'no-store',
        headers: { Accept: 'application/json' },
      });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      return (await r.json()) as T;
    } finally {
      clearTimeout(to);
    }
  }

  private async refreshOhlc() {
    clearTimeout(this.ohlcTimer);
    if (this.stopped) return;
    try {
      if (!document.hidden) {
        const r = await this.get<{
          data: { attributes: { ohlcv_list: [number, number, number, number, number, number][] } };
        }>(
          `/networks/cardano/pools/${POOL}/ohlcv/minute?aggregate=${PERIOD_MIN}&limit=${MAX_CANDLES + 4}&currency=usd`,
        );
        const rows = r?.data?.attributes?.ohlcv_list;
        if (Array.isArray(rows) && rows.length > 0) {
          const live = this.candles[this.candles.length - 1];
          this.candles = fillGaps(rows.map(([ts, o, h, l, c]) => ({ t: ts * 1000, o, h, l, c })));
          // keep the live candle if we already extended it past the API's newest one
          const last = this.candles[this.candles.length - 1];
          if (this.real && live && live.t === last.t && this.price != null) {
            last.c = this.price;
            last.h = Math.max(last.h, this.price);
            last.l = Math.min(last.l, this.price);
          }
          this.real = true;
          this.ok();
        }
      }
    } catch (e) {
      console.warn('[market]', e);
      this.fail();
    }
    this.ohlcTimer = window.setTimeout(() => this.refreshOhlc(), OHLC_EVERY * this.backoff);
  }

  private async refreshPrice() {
    clearTimeout(this.priceTimer);
    if (this.stopped) return;
    try {
      if (!document.hidden) {
        const r = await this.get<{
          data: {
            attributes: {
              base_token_price_usd: string;
              price_change_percentage?: { h24?: string };
            };
          };
        }>(`/networks/cardano/pools/${POOL}`);
        const at = r?.data?.attributes;
        const p = at ? parseFloat(at.base_token_price_usd) : NaN;
        if (Number.isFinite(p) && p > 0) {
          const ch =
            at.price_change_percentage?.h24 != null
              ? parseFloat(at.price_change_percentage.h24)
              : this.change24h;
          const changed = p !== this.price || ch !== this.change24h || this.status !== 'live';
          this.price = p;
          this.change24h = ch;
          this.pushTick(p, Date.now());
          this.checkedAt = Date.now();
          if (changed) this.ok();
          else {
            this.backoff = 1; // same numbers: only the quote time moves on
            this.version++;
          }
        }
      }
    } catch (e) {
      console.warn('[market]', e);
      this.fail();
    }
    this.priceTimer = window.setTimeout(() => this.refreshPrice(), PRICE_EVERY * this.backoff);
  }

  /** feed the newest price into the candles: extend the current candle or open a new one */
  private pushTick(p: number, now: number) {
    const last = this.candles[this.candles.length - 1];
    if (!last || !this.real) return;
    if (now - last.t >= PERIOD) {
      const t = last.t + Math.floor((now - last.t) / PERIOD) * PERIOD;
      this.candles.push({ t, o: last.c, h: Math.max(last.c, p), l: Math.min(last.c, p), c: p });
      if (this.candles.length > MAX_CANDLES) this.candles.shift();
    } else {
      last.c = p;
      last.h = Math.max(last.h, p);
      last.l = Math.min(last.l, p);
    }
  }

  private ok() {
    this.backoff = 1;
    this.checkedAt = Date.now();
    this.status = this.real ? 'live' : 'demo';
    this.updatedAt = Date.now();
    this.version++;
    if (this.real) this.saveCache();
  }

  private fail() {
    // rate limited or offline: slow down and fall back to what we have
    this.backoff = Math.min(8, this.backoff * 2);
    const next: MarketStatus = this.real ? 'offline' : 'demo';
    if (next !== this.status) {
      this.status = next;
      if (!this.real) this.candles = demoCandles();
      this.version++;
    }
  }

  // ---------------------------------------------------------------- cache
  private loadCache() {
    try {
      const raw = localStorage.getItem(CACHE_KEY);
      if (!raw) return;
      const c = JSON.parse(raw) as {
        candles: Candle[];
        price: number | null;
        change24h: number | null;
        at: number;
      };
      if (!Array.isArray(c.candles) || !c.candles.length) return;
      this.candles = c.candles;
      this.real = true;
      this.price = c.price;
      this.change24h = c.change24h;
      this.updatedAt = c.at;
      this.checkedAt = c.at;
      this.status = 'loading'; // shown as "updating" until the first live answer
      this.version++;
    } catch {
      /* ignore broken cache */
    }
  }

  private saveCache() {
    try {
      localStorage.setItem(
        CACHE_KEY,
        JSON.stringify({
          candles: this.candles,
          price: this.price,
          change24h: this.change24h,
          at: this.updatedAt,
        }),
      );
    } catch {
      /* private mode etc. */
    }
  }
}

/**
 * GeckoTerminal only returns candles for periods that had trades (newest first).
 * Turn that into a continuous 24h series: empty periods become flat candles at the last close.
 */
function fillGaps(rows: Candle[]): Candle[] {
  const byT = new Map(rows.map((c) => [c.t, c]));
  const nowStart = Math.floor(Date.now() / PERIOD) * PERIOD;
  const oldest = rows.reduce((m, c) => Math.min(m, c.t), Infinity);
  // seed with the last known close before our 24h window
  let prev =
    rows.filter((c) => c.t < nowStart - (MAX_CANDLES - 1) * PERIOD).sort((a, b) => b.t - a.t)[0]
      ?.c ?? rows[rows.length - 1].o;
  const out: Candle[] = [];
  for (let i = MAX_CANDLES - 1; i >= 0; i--) {
    const t = nowStart - i * PERIOD;
    const c = byT.get(t);
    if (c) {
      out.push({ ...c });
      prev = c.c;
    } else if (t >= oldest || out.length) {
      out.push({ t, o: prev, h: prev, l: prev, c: prev });
    }
  }
  return out;
}

/** clearly-labelled placeholder when we have never managed to load real data */
function demoCandles(): Candle[] {
  const out: Candle[] = [];
  let p = 0.0005;
  const start = Date.now() - MAX_CANDLES * PERIOD;
  for (let i = 0; i < MAX_CANDLES; i++) {
    const o = p;
    p = Math.max(0.0001, p * (1 + (Math.random() - 0.47) * 0.04));
    out.push({
      t: start + i * PERIOD,
      o,
      h: Math.max(o, p) * (1 + Math.random() * 0.01),
      l: Math.min(o, p) * (1 - Math.random() * 0.01),
      c: p,
    });
  }
  return out;
}
