// The night sky behind the jar: twinkling stars, the odd shooting star, and a SNEK-piloted UFO.
import * as THREE from 'three';

/** vertical screen band (NDC, -1..1) where the sky is actually visible above the jar */
export type SkyBand = () => [number, number];

const STAR_COUNT = 1500;

export class Sky {
  private stars: THREE.Points<THREE.BufferGeometry, THREE.ShaderMaterial>;
  private time = 0;
  private meteors: Meteor[] = [];
  private nextMeteor = 1.5;
  private ufo: Ufo;
  private nextUfo = 9 + Math.random() * 6;
  private ray = new THREE.Raycaster();

  constructor(
    private scene: THREE.Scene,
    private band: SkyBand,
    pilot: THREE.Texture,
  ) {
    this.stars = makeStars();
    scene.add(this.stars);
    this.ufo = new Ufo(pilot);
    scene.add(this.ufo.root);
  }

  update(dt: number, camera: THREE.PerspectiveCamera, pixelRatio: number) {
    this.time += dt;
    const u = this.stars.material.uniforms;
    u.uTime.value = this.time;
    u.uPixelRatio.value = pixelRatio;

    // shooting stars
    this.nextMeteor -= dt;
    if (this.nextMeteor <= 0) {
      this.spawnMeteor(camera);
      if (Math.random() < 0.2)
        setTimeout(() => this.spawnMeteor(camera), 180 + Math.random() * 250);
      this.nextMeteor = 2.5 + Math.random() * 5;
    }
    for (const m of this.meteors) m.update(dt);
    this.meteors = this.meteors.filter((m) => {
      if (m.alive) return true;
      this.scene.remove(m.mesh);
      m.mesh.material.dispose();
      return false;
    });

    // UFO
    this.nextUfo -= dt;
    if (this.nextUfo <= 0 && !this.ufo.active) {
      const [lo, hi] = this.flightBand();
      const ndcY = lo + (hi - lo) * (0.35 + Math.random() * 0.3);
      const dir = Math.random() < 0.5 ? 1 : -1;
      const z = -12;
      const from = this.worldAt(camera, -1.25 * dir, ndcY, z);
      const hover = this.worldAt(camera, (Math.random() - 0.5) * 0.7, ndcY, z);
      const to = this.worldAt(camera, 1.25 * dir, ndcY + 0.06, z);
      this.ufo.launch(from, hover, to);
      this.nextUfo = 22 + Math.random() * 20;
    }
    this.ufo.update(dt);
  }

  private flightBand(): [number, number] {
    const [lo, hi] = this.band();
    // on wide screens the band above the jar can be thin: fly a bit higher, the sides are visible anyway
    return hi - lo < 0.1 ? [0.55, 0.85] : [lo, hi];
  }

  private spawnMeteor(camera: THREE.PerspectiveCamera) {
    const [lo, hi] = this.flightBand();
    const z = -20 - Math.random() * 6;
    const dir = Math.random() < 0.5 ? 1 : -1;
    const start = this.worldAt(
      camera,
      Math.random() * 1.4 - 0.7 - dir * 0.3,
      Math.min(1.05, hi + 0.1) - Math.random() * Math.max(0.15, hi - lo),
      z,
    );
    const angle = THREE.MathUtils.degToRad(18 + Math.random() * 22);
    const vel = new THREE.Vector3(Math.cos(angle) * dir, -Math.sin(angle), 0).multiplyScalar(
      16 + Math.random() * 10,
    );
    const m = new Meteor(start, vel, 2.2 + Math.random() * 2.2);
    this.scene.add(m.mesh);
    this.meteors.push(m);
  }

  /** point on the plane z that sits under the given NDC position */
  private worldAt(camera: THREE.PerspectiveCamera, x: number, y: number, z: number) {
    this.ray.setFromCamera(new THREE.Vector2(x, y), camera);
    const hit = new THREE.Vector3();
    this.ray.ray.intersectPlane(new THREE.Plane(new THREE.Vector3(0, 0, 1), -z), hit);
    return hit;
  }
}

// ---------------------------------------------------------------- stars
function makeStars() {
  const pos = new Float32Array(STAR_COUNT * 3);
  const col = new Float32Array(STAR_COUNT * 3);
  const size = new Float32Array(STAR_COUNT);
  const phase = new Float32Array(STAR_COUNT);
  const speed = new Float32Array(STAR_COUNT);
  const tints = ['#ffffff', '#ffffff', '#ffffff', '#d8ffe9', '#cfe3ff', '#fff2c4', '#ffd6f0'].map(
    (c) => new THREE.Color(c),
  );
  for (let i = 0; i < STAR_COUNT; i++) {
    pos[i * 3] = (Math.random() - 0.5) * 56;
    pos[i * 3 + 1] = Math.random() * 46 - 12;
    pos[i * 3 + 2] = -20 - Math.random() * 16;
    const c = tints[Math.floor(Math.random() * tints.length)];
    col.set([c.r, c.g, c.b], i * 3);
    // mostly tiny, a few big bright ones
    const r = Math.random();
    size[i] =
      r < 0.82
        ? 0.45 + Math.random() * 0.5
        : r < 0.97
          ? 1.0 + Math.random() * 0.6
          : 1.7 + Math.random() * 0.6;
    phase[i] = Math.random() * Math.PI * 2;
    speed[i] = 0.6 + Math.random() * 2.6;
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('aColor', new THREE.BufferAttribute(col, 3));
  geo.setAttribute('aSize', new THREE.BufferAttribute(size, 1));
  geo.setAttribute('aPhase', new THREE.BufferAttribute(phase, 1));
  geo.setAttribute('aSpeed', new THREE.BufferAttribute(speed, 1));
  const mat = new THREE.ShaderMaterial({
    uniforms: { uTime: { value: 0 }, uPixelRatio: { value: 1 } },
    vertexShader: /* glsl */ `
      attribute vec3 aColor;
      attribute float aSize;
      attribute float aPhase;
      attribute float aSpeed;
      uniform float uTime;
      uniform float uPixelRatio;
      varying vec3 vColor;
      varying float vAlpha;
      varying float vGlare;
      void main() {
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        float s = 0.5 + 0.5 * sin(uTime * aSpeed + aPhase);
        // occasional deeper dips make the twinkle feel less mechanical
        s *= 0.75 + 0.25 * sin(uTime * aSpeed * 0.37 + aPhase * 2.1);
        vAlpha = mix(0.25, 1.0, s * s);
        vColor = aColor;
        vGlare = smoothstep(1.5, 2.2, aSize);
        gl_PointSize = aSize * uPixelRatio * (0.7 + 0.45 * s) * (300.0 / -mv.z) * (1.0 + vGlare * 1.6);
        gl_Position = projectionMatrix * mv;
      }`,
    fragmentShader: /* glsl */ `
      varying vec3 vColor;
      varying float vAlpha;
      varying float vGlare;
      void main() {
        vec2 p = gl_PointCoord - 0.5;
        float d = length(p);
        float core = pow(smoothstep(0.5, 0.0, d), mix(2.4, 5.0, vGlare));
        float cross = (max(0.0, 1.0 - abs(p.x) * 16.0) * smoothstep(0.5, 0.0, abs(p.y))
                     + max(0.0, 1.0 - abs(p.y) * 16.0) * smoothstep(0.5, 0.0, abs(p.x))) * vGlare;
        float a = (core + cross * 0.8) * vAlpha;
        if (a < 0.01) discard;
        gl_FragColor = vec4(vColor, a);
      }`,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
  });
  const pts = new THREE.Points(geo, mat);
  pts.frustumCulled = false;
  return pts;
}

// ---------------------------------------------------------------- shooting star
let meteorTex: THREE.Texture | null = null;
function meteorTexture() {
  if (meteorTex) return meteorTex;
  const c = document.createElement('canvas');
  c.width = 256;
  c.height = 32;
  const g = c.getContext('2d')!;
  const tail = g.createLinearGradient(0, 0, 256, 0);
  tail.addColorStop(0, 'rgba(160,255,210,0)');
  tail.addColorStop(0.75, 'rgba(200,255,230,0.55)');
  tail.addColorStop(1, 'rgba(255,255,255,1)');
  g.fillStyle = tail;
  g.beginPath();
  g.moveTo(0, 16);
  g.lineTo(250, 11);
  g.lineTo(250, 21);
  g.closePath();
  g.fill();
  const head = g.createRadialGradient(246, 16, 0, 246, 16, 14);
  head.addColorStop(0, 'rgba(255,255,255,1)');
  head.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = head;
  g.fillRect(226, 0, 30, 32);
  meteorTex = new THREE.CanvasTexture(c);
  meteorTex.colorSpace = THREE.SRGBColorSpace;
  return meteorTex;
}

class Meteor {
  mesh: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial>;
  alive = true;
  private t = 0;
  private life = 0.9 + Math.random() * 0.4;

  constructor(
    start: THREE.Vector3,
    private vel: THREE.Vector3,
    private len: number,
  ) {
    const geo = new THREE.PlaneGeometry(1, 1);
    geo.translate(-0.5, 0, 0); // head at the origin, tail trails behind
    this.mesh = new THREE.Mesh(
      geo,
      new THREE.MeshBasicMaterial({
        map: meteorTexture(),
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        fog: false,
        toneMapped: false,
      }),
    );
    this.mesh.position.copy(start);
    this.mesh.rotation.z = Math.atan2(vel.y, vel.x);
    this.mesh.scale.set(0.01, 0.18, 1);
  }

  update(dt: number) {
    this.t += dt;
    const k = this.t / this.life;
    this.mesh.position.addScaledVector(this.vel, dt);
    // tail grows in, then the whole streak fades
    this.mesh.scale.x = this.len * Math.min(1, k * 3.5);
    this.mesh.material.opacity = k < 0.6 ? 1 : Math.max(0, 1 - (k - 0.6) / 0.4);
    if (k >= 1) this.alive = false;
  }
}

// ---------------------------------------------------------------- UFO
class Ufo {
  root = new THREE.Group();
  active = false;
  private body = new THREE.Group();
  private lights: THREE.Mesh<THREE.SphereGeometry, THREE.MeshBasicMaterial>[] = [];
  private beam: THREE.Mesh<THREE.ConeGeometry, THREE.MeshBasicMaterial>;
  private t = 0;
  private from = new THREE.Vector3();
  private hover = new THREE.Vector3();
  private to = new THREE.Vector3();
  private static ENTER = 3.2;
  private static HOVER = 1.8;
  private static EXIT = 1.1;

  constructor(pilot: THREE.Texture) {
    const hull = new THREE.Mesh(
      new THREE.SphereGeometry(0.7, 40, 16),
      new THREE.MeshStandardMaterial({ color: 0xa7b4c4, metalness: 0.85, roughness: 0.28 }),
    );
    hull.scale.set(1, 0.24, 1);
    const belly = new THREE.Mesh(
      new THREE.SphereGeometry(0.34, 24, 10, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2),
      new THREE.MeshStandardMaterial({ color: 0x5b6676, metalness: 0.7, roughness: 0.4 }),
    );
    belly.position.y = -0.08;
    belly.scale.y = 0.45;
    const glowDisk = new THREE.Mesh(
      new THREE.CircleGeometry(0.2, 24),
      new THREE.MeshBasicMaterial({ color: 0x7dffbf, toneMapped: false }),
    );
    glowDisk.rotation.x = Math.PI / 2;
    glowDisk.position.y = -0.235;

    // glass dome with a tiny SNEK at the controls
    const seat = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: pilot,
        transparent: true,
        depthWrite: false,
        fog: false,
        toneMapped: false,
      }),
    );
    seat.scale.setScalar(0.5);
    seat.position.y = 0.26;
    seat.renderOrder = 1;
    const dome = new THREE.Mesh(
      new THREE.SphereGeometry(0.34, 28, 14, 0, Math.PI * 2, 0, Math.PI / 2),
      new THREE.MeshPhysicalMaterial({
        color: 0x9ff8ff,
        transparent: true,
        opacity: 0.32,
        roughness: 0.05,
        metalness: 0,
        clearcoat: 1,
        depthWrite: false,
      }),
    );
    dome.position.y = 0.1;
    dome.renderOrder = 2;

    // running lights around the rim
    const lightGeo = new THREE.SphereGeometry(0.055, 10, 8);
    for (let i = 0; i < 10; i++) {
      const a = (i / 10) * Math.PI * 2;
      const l = new THREE.Mesh(
        lightGeo,
        new THREE.MeshBasicMaterial({ color: 0xffffff, toneMapped: false }),
      );
      l.position.set(Math.cos(a) * 0.6, -0.03, Math.sin(a) * 0.6);
      this.lights.push(l);
      this.body.add(l);
    }

    this.beam = new THREE.Mesh(
      new THREE.ConeGeometry(0.62, 2.6, 28, 1, true),
      new THREE.MeshBasicMaterial({
        color: 0x69f0ae,
        transparent: true,
        opacity: 0,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        side: THREE.DoubleSide,
        fog: false,
        toneMapped: false,
      }),
    );
    this.beam.position.y = -1.5;

    this.body.add(hull, belly, glowDisk, seat, dome, this.beam);
    this.root.add(this.body);
    this.root.visible = false;
  }

  launch(from: THREE.Vector3, hover: THREE.Vector3, to: THREE.Vector3) {
    this.from.copy(from);
    this.hover.copy(hover);
    this.to.copy(to);
    this.t = 0;
    this.active = true;
    this.root.visible = true;
    this.root.position.copy(from);
  }

  update(dt: number) {
    if (!this.active) return;
    this.t += dt;
    const { ENTER, HOVER, EXIT } = Ufo;
    const t = this.t;
    const ease = (k: number) => k * k * (3 - 2 * k);
    let tilt = 0;
    let beam = 0;
    if (t < ENTER) {
      const k = ease(t / ENTER);
      this.root.position.lerpVectors(this.from, this.hover, k);
      this.root.position.y += Math.sin(k * Math.PI * 2) * 0.35;
      tilt = (this.hover.x - this.from.x > 0 ? -1 : 1) * 0.22 * (1 - k);
    } else if (t < ENTER + HOVER) {
      const k = (t - ENTER) / HOVER;
      this.root.position.copy(this.hover);
      this.root.position.y += Math.sin(k * Math.PI * 4) * 0.06;
      tilt = Math.sin(k * Math.PI * 6) * 0.05;
      beam = Math.sin(k * Math.PI) * (0.55 + 0.25 * Math.sin(t * 30));
    } else if (t < ENTER + HOVER + EXIT) {
      const k = (t - ENTER - HOVER) / EXIT;
      // wind-up, then zip away
      const e = k * k * k;
      this.root.position.lerpVectors(this.hover, this.to, e);
      this.root.position.y += Math.sin(k * Math.PI) * 0.5;
      tilt = (this.to.x - this.hover.x > 0 ? -1 : 1) * 0.35 * Math.min(1, k * 3);
    } else {
      this.active = false;
      this.root.visible = false;
      return;
    }
    this.body.rotation.z = tilt;
    this.body.rotation.y += dt * 1.4;
    this.beam.material.opacity = beam * 0.45;
    this.beam.visible = beam > 0.01;
    // chasing rim lights
    const palette = [0x00e676, 0xffea00, 0xff4fd8];
    this.lights.forEach((l, i) => {
      const on = (Math.floor(t * 8) + i) % 3;
      l.material.color.setHex(palette[on]);
    });
  }
}
