// The candlestick chart on the jar's back panel, drawn from real SNEK market data.
// It eases between updates (scale, last close) so new ticks glide in instead of jumping,
// and exposes its price/time mapping so frames (e.g. the trading terminal) can line up with it.
import * as THREE from 'three';
import { PERIOD_MIN, type Market } from './market';

export interface MarketView {
  status: Market['status'];
  /** changes whenever anything a view might draw has changed */
  version: number;
  price: number | null;
  change24h: number | null;
  /** is the live candle up from its open? */
  up: boolean;
  /** world y (on the back panel) of the current, eased price */
  priceY: number | null;
  /** price grid lines: world y on the back panel + label */
  ticks: { y: number; label: string }[];
  /** time labels: world x on the back panel + label */
  timeTicks: { x: number; label: string }[];
  /** when the shown price was last confirmed (ms), null before the first answer */
  quoteTime: number | null;
}

/** "14:32:05" in the player's local time */
export function fmtClock(t: number) {
  return new Date(t).toLocaleTimeString('en-GB', { hour12: false });
}

/** label for the quote time in the page's current language */
export function quoteLabel() {
  const l = document.documentElement.lang;
  return l === 'zh-Hans' ? '报价时间' : l.startsWith('zh') ? '報價時間' : 'as of';
}

interface Dims {
  w: number;
  h: number;
  t: number;
  backZ: number;
}

const CW = 720;
const GREEN = '#00e676';
const RED = '#ff1744';

export class ChartPanel implements MarketView {
  mesh: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshStandardMaterial>;
  status: Market['status'] = 'loading';
  version = 0;
  price: number | null = null;
  change24h: number | null = null;
  up = true;
  priceY: number | null = null;
  ticks: { y: number; label: string }[] = [];
  timeTicks: { x: number; label: string }[] = [];
  quoteTime: number | null = null;

  private lang = '';
  private canvas = document.createElement('canvas');
  private g: CanvasRenderingContext2D;
  private tex: THREE.CanvasTexture;
  private pulse: THREE.Sprite;
  private PW: number;
  private PH: number;
  private CH: number;
  private seen = -1;
  private lo = 0;
  private hi = 1;
  private close = 0; // eased last close
  private dirty = true;
  private sinceDraw = 0;
  private time = 0;
  /** terminal frame draws its own axis + price tag */
  private compact = false;

  constructor(
    private market: Market,
    private d: Dims,
  ) {
    this.PW = d.w + 2 * d.t;
    this.PH = d.h + 0.6;
    this.CH = Math.round((CW * this.PH) / this.PW);
    this.canvas.width = CW;
    this.canvas.height = this.CH;
    this.g = this.canvas.getContext('2d')!;
    this.tex = new THREE.CanvasTexture(this.canvas);
    this.tex.colorSpace = THREE.SRGBColorSpace;
    this.tex.anisotropy = 4;
    this.mesh = new THREE.Mesh(
      new THREE.PlaneGeometry(this.PW, this.PH),
      new THREE.MeshStandardMaterial({ map: this.tex, roughness: 1, metalness: 0 }),
    );
    this.mesh.position.set(0, d.h / 2 + 0.2, d.backZ);
    this.mesh.receiveShadow = true;

    // soft pulsing dot on the live price
    const c = document.createElement('canvas');
    c.width = c.height = 64;
    const pg = c.getContext('2d')!;
    const gr = pg.createRadialGradient(32, 32, 0, 32, 32, 32);
    gr.addColorStop(0, 'rgba(255,255,255,1)');
    gr.addColorStop(0.25, 'rgba(160,255,210,0.9)');
    gr.addColorStop(1, 'rgba(0,230,118,0)');
    pg.fillStyle = gr;
    pg.fillRect(0, 0, 64, 64);
    const pt = new THREE.CanvasTexture(c);
    pt.colorSpace = THREE.SRGBColorSpace;
    this.pulse = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: pt,
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        toneMapped: false,
        fog: false,
      }),
    );
    this.pulse.scale.setScalar(0.3);
    this.mesh.add(this.pulse);
  }

  setCompact(on: boolean) {
    if (this.compact === on) return;
    this.compact = on;
    this.dirty = true;
  }

  // ---------------------------------------------------------------- layout (world units)
  private get x0() {
    return -this.d.w / 2 + 0.14;
  }
  private get x1() {
    return this.d.w / 2 - (this.compact ? 0.22 : 0.95);
  }
  private get y0() {
    return 0.35;
  }
  private get y1() {
    return this.d.h - 0.85;
  }
  private yOf(p: number) {
    return this.y0 + ((p - this.lo) / (this.hi - this.lo || 1)) * (this.y1 - this.y0);
  }
  /** world -> canvas px */
  private px(x: number) {
    return (x / this.PW + 0.5) * CW;
  }
  private py(y: number) {
    return (0.5 - (y - (this.d.h / 2 + 0.2)) / this.PH) * this.CH;
  }

  // ---------------------------------------------------------------- update
  update(dt: number) {
    this.time += dt;
    const m = this.market;
    const cs = m.candles;
    if (m.version !== this.seen && cs.length) {
      this.seen = m.version;
      this.status = m.status;
      this.price = m.price;
      this.change24h = m.change24h;
      this.quoteTime = m.checkedAt || m.updatedAt || null;
      if (this.close === 0) {
        // first data: no easing from zero
        this.close = cs[cs.length - 1].c;
        [this.lo, this.hi] = this.range();
      }
      this.dirty = true;
    }
    if (!cs.length) return;
    if (document.documentElement.lang !== this.lang) {
      this.lang = document.documentElement.lang;
      this.dirty = true;
    }

    // ease the scale and the live close so updates glide in
    const [tlo, thi] = this.range();
    const k = 1 - Math.exp(-dt * 3);
    const last = cs[cs.length - 1];
    const before = this.lo + this.hi + this.close;
    this.lo += (tlo - this.lo) * k;
    this.hi += (thi - this.hi) * k;
    this.close += (last.c - this.close) * k;
    if (Math.abs(this.lo + this.hi + this.close - before) > (thi - tlo) * 1e-4) this.dirty = true;
    this.up = this.close >= last.o;

    this.sinceDraw += dt;
    if (this.dirty && this.sinceDraw > 1 / 20) {
      this.draw();
      this.dirty = false;
      this.sinceDraw = 0;
    }

    // pulse on the live price (the sprite lives in the panel's local space)
    const slot = (this.x1 - this.x0) / cs.length;
    const lx = this.x0 + slot * (cs.length - 0.5);
    this.priceY = this.yOf(this.close);
    this.pulse.position.set(lx, this.priceY - (this.d.h / 2 + 0.2), 0.02);
    const s = 0.22 + 0.1 * (0.5 + 0.5 * Math.sin(this.time * 4));
    this.pulse.scale.setScalar(s);
    this.pulse.material.color.set(this.up ? 0xffffff : 0xffb3c0);
    this.pulse.material.opacity = this.status === 'demo' ? 0.3 : 1;
  }

  private range(): [number, number] {
    const cs = this.market.candles;
    let lo = Infinity;
    let hi = -Infinity;
    for (const c of cs) {
      lo = Math.min(lo, c.l);
      hi = Math.max(hi, c.h);
    }
    const pad = (hi - lo) * 0.12 || hi * 0.02;
    return [lo - pad, hi + pad];
  }

  // ---------------------------------------------------------------- drawing
  private draw() {
    const g = this.g;
    const cs = this.market.candles;
    const H = this.CH;

    const bg = g.createLinearGradient(0, 0, 0, H);
    bg.addColorStop(0, '#16201b');
    bg.addColorStop(1, '#0e1411');
    g.fillStyle = bg;
    g.fillRect(0, 0, CW, H);
    g.strokeStyle = 'rgba(105,240,174,0.05)';
    g.lineWidth = 1;
    for (let x = 0; x <= CW; x += 36) {
      g.beginPath();
      g.moveTo(x + 0.5, 0);
      g.lineTo(x + 0.5, H);
      g.stroke();
    }
    for (let y = 0; y <= H; y += 36) {
      g.beginPath();
      g.moveTo(0, y + 0.5);
      g.lineTo(CW, y + 0.5);
      g.stroke();
    }

    // big faint watermark
    g.font = 'bold 54px "Arial Black", Arial, sans-serif';
    g.fillStyle = 'rgba(0,230,118,0.07)';
    g.textBaseline = 'alphabetic';
    g.fillText('$SNEK', this.px(this.x0), this.py(this.d.h * 0.62));

    // price grid + labels (nice round steps)
    const ticks = niceTicks(this.lo, this.hi, 6);
    this.ticks = ticks.map((p) => ({ y: this.yOf(p), label: fmtPrice(p) }));
    g.font = '600 15px "Consolas", "Menlo", monospace';
    g.textBaseline = 'middle';
    for (const tk of this.ticks) {
      const y = this.py(tk.y);
      g.strokeStyle = 'rgba(105,240,174,0.1)';
      g.setLineDash([4, 6]);
      g.beginPath();
      g.moveTo(this.px(this.x0), y);
      g.lineTo(this.px(this.x1), y);
      g.stroke();
      g.setLineDash([]);
      if (!this.compact) {
        g.fillStyle = 'rgba(160,200,180,0.55)';
        g.fillText(tk.label, this.px(this.x1) + 8, y);
      }
    }

    // candles
    const n = cs.length;
    const slot = (this.x1 - this.x0) / Math.max(1, n);
    const bodyW = Math.max(3, this.px(this.x0 + slot * 0.74) - this.px(this.x0));
    this.timeTicks = [];
    cs.forEach((c, i) => {
      const live = i === n - 1;
      const close = live ? this.close : c.c;
      const hi = live ? Math.max(c.h, close) : c.h;
      const lo = live ? Math.min(c.l, close) : c.l;
      const up = close >= c.o;
      const cx = this.px(this.x0 + slot * (i + 0.5));
      // a period with no trades: faint dash at the unchanged price (how exchanges draw it)
      if (!live && c.o === c.h && c.h === c.l && c.l === c.c) {
        g.fillStyle = 'rgba(150,190,170,0.28)';
        g.fillRect(cx - bodyW / 2, this.py(this.yOf(c.c)) - 1, bodyW, 2);
        const d0 = new Date(c.t);
        if (d0.getMinutes() === 0 && d0.getHours() % 4 === 0)
          this.timeTicks.push({
            x: this.x0 + slot * (i + 0.5),
            label: `${String(d0.getHours()).padStart(2, '0')}:00`,
          });
        return;
      }
      const a = live ? 0.95 : 0.5;
      const col = up ? `rgba(0,230,118,${a})` : `rgba(255,23,68,${a})`;
      g.strokeStyle = col;
      g.lineWidth = live ? 2.5 : 1.6;
      g.beginPath();
      g.moveTo(cx, this.py(this.yOf(hi)));
      g.lineTo(cx, this.py(this.yOf(lo)));
      g.stroke();
      const yTop = this.py(this.yOf(Math.max(c.o, close)));
      const yBot = this.py(this.yOf(Math.min(c.o, close)));
      g.fillStyle = up ? `rgba(0,230,118,${a * 0.75})` : `rgba(255,23,68,${a * 0.75})`;
      g.fillRect(cx - bodyW / 2, yTop, bodyW, Math.max(2, yBot - yTop));
      if (live) {
        g.strokeStyle = up ? GREEN : RED;
        g.lineWidth = 2;
        g.strokeRect(cx - bodyW / 2, yTop, bodyW, Math.max(2, yBot - yTop));
      }
      // a time label every ~4 hours
      const d = new Date(c.t);
      if (d.getMinutes() === 0 && d.getHours() % 4 === 0) {
        this.timeTicks.push({
          x: this.x0 + slot * (i + 0.5),
          label: `${String(d.getHours()).padStart(2, '0')}:00`,
        });
      }
    });

    // current price line + tag
    const py = this.py(this.yOf(this.close));
    const col = this.up ? GREEN : RED;
    g.strokeStyle = this.up ? 'rgba(0,230,118,0.6)' : 'rgba(255,23,68,0.6)';
    g.setLineDash([6, 5]);
    g.lineWidth = 1.5;
    g.beginPath();
    g.moveTo(this.px(this.x0), py);
    g.lineTo(this.px(this.compact ? this.d.w / 2 : this.x1), py);
    g.stroke();
    g.setLineDash([]);
    if (!this.compact) {
      const tx = this.px(this.x1) + 4;
      g.fillStyle = col;
      g.beginPath();
      g.roundRect(tx, py - 13, this.px(this.d.w / 2) - tx - 4, 26, 5);
      g.fill();
      g.fillStyle = '#04140c';
      g.font = '800 15px "Consolas", "Menlo", monospace';
      g.fillText(fmtPrice(this.close), tx + 6, py + 1);
    }

    // header: pair, price, 24h change, status
    const hx = this.px(this.x0);
    const hy = this.py(this.d.h - 0.32);
    g.textBaseline = 'middle';
    if (!this.compact) {
      g.font = '800 22px "Consolas", "Menlo", monospace';
      g.fillStyle = 'rgba(234,255,243,0.85)';
      g.fillText('SNEK/USD', hx, hy);
      let x = hx + g.measureText('SNEK/USD').width + 12;
      g.font = '700 15px "Consolas", "Menlo", monospace';
      g.fillStyle = 'rgba(105,240,174,0.7)';
      g.fillText(`${PERIOD_MIN}m`, x, hy + 1);
      x += g.measureText(`${PERIOD_MIN}m`).width + 14;
      if (this.price != null) {
        g.font = '800 20px "Consolas", "Menlo", monospace';
        g.fillStyle = 'rgba(234,255,243,0.9)';
        const ptxt = `$${fmtPrice(this.price)}`;
        g.fillText(ptxt, x, hy);
        x += g.measureText(ptxt).width + 10;
      }
      if (this.change24h != null) {
        const ch = this.change24h;
        g.font = '800 17px "Consolas", "Menlo", monospace';
        g.fillStyle = ch >= 0 ? GREEN : RED;
        g.fillText(`${ch >= 0 ? '+' : ''}${ch.toFixed(2)}%`, x, hy + 1);
      }
      if (this.quoteTime) {
        g.font = '600 14px "Consolas", "Menlo", monospace';
        g.fillStyle = this.status === 'offline' ? '#ffb300' : 'rgba(190,225,205,0.75)';
        g.fillText(`${quoteLabel()} ${fmtClock(this.quoteTime)}`, hx, hy + 24);
      }
    } // the terminal frame shows pair / price / change in its title bar
    // status pill on the right of the header
    const st = {
      live: ['LIVE', GREEN],
      offline: ['OFFLINE', '#ffb300'],
      demo: ['DEMO', '#8aa596'],
      loading: ['UPDATING', '#8aa596'],
    }[this.status];
    g.font = '800 13px "Consolas", "Menlo", monospace';
    const sw = g.measureText(st[0]).width + 26;
    const sx = this.px(this.d.w / 2 - 0.12) - sw;
    g.fillStyle = 'rgba(0,0,0,0.35)';
    g.beginPath();
    g.roundRect(sx, hy - 12, sw, 24, 12);
    g.fill();
    g.fillStyle = st[1];
    g.beginPath();
    g.arc(sx + 11, hy, 4.5, 0, Math.PI * 2);
    g.fill();
    g.fillText(st[0], sx + 20, hy + 1);
    // data credit (CoinGecko's free API asks for attribution)
    g.font = '600 12px system-ui, sans-serif';
    g.fillStyle = 'rgba(160,200,180,0.45)';
    g.fillText(
      this.status === 'demo' ? 'Demo data · offline' : 'Data: GeckoTerminal · Minswap',
      hx,
      hy + (this.compact || !this.quoteTime ? 24 : 44),
    );

    this.tex.needsUpdate = true;
    this.version++;
  }
}

function niceTicks(lo: number, hi: number, count: number) {
  const raw = (hi - lo) / count;
  const mag = Math.pow(10, Math.floor(Math.log10(raw)));
  const step = [1, 2, 2.5, 5, 10].map((m) => m * mag).find((s) => s >= raw) ?? raw;
  const out: number[] = [];
  for (let v = Math.ceil(lo / step) * step; v <= hi; v += step) out.push(v);
  return out;
}

/** 0.00048123 -> "0.0004812" (5 significant digits, no exponent) */
export function fmtPrice(p: number) {
  if (p >= 1) return p.toFixed(2);
  const digits = Math.min(10, Math.max(4, 4 - Math.floor(Math.log10(p))));
  return p.toFixed(digits);
}
