// Jar frame styles. Every style obeys the same rule: the inner edge of the frame sits exactly on
// the physics boundary in the play plane (z = 0) and the frame only extends towards the camera,
// so perspective never makes a head look like it is inside a wall or floating above the floor.
import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { fmtClock, fmtPrice, quoteLabel, type MarketView } from './chart';
import { PERIOD_MIN } from './market';

/** live chart + a way to map a point on the back panel onto a plane closer to the camera */
export interface JarContext {
  view: MarketView;
  project(x: number, y: number, z: number): { x: number; y: number };
}

export type FrameStyle = 'glass' | 'terminal' | 'capsule' | 'neon';
export const FRAME_STYLES: FrameStyle[] = ['glass', 'terminal', 'capsule', 'neon'];

export interface JarDims {
  w: number; // inner width (world units)
  h: number; // inner height
  t: number; // wall thickness
  depth: number; // frame depth towards the camera
  dangerY: number; // world y of the red line
  backZ: number; // z of the chart panel behind the jar
}

export interface Jar {
  group: THREE.Group;
  /** radius of the rounded inner bottom corners (world units); physics adds matching fillets */
  innerRadius: number;
  /** world y of the highest part of the frame (the sky starts above it) */
  top: number;
  update(dt: number, ctx: JarContext): void;
}

const GREEN = '#00e676';
const TOP_EXTRA = 0.25;

export function buildJar(style: FrameStyle, d: JarDims): Jar {
  switch (style) {
    case 'glass':
      return glassJar(d);
    case 'terminal':
      return terminalJar(d);
    case 'capsule':
      return capsuleJar(d);
    default:
      return neonJar(d);
  }
}

// ====================================================================== shared helpers
function uPath(p: THREE.Path, d: JarDims, outerR: number, innerR: number, close: boolean) {
  const { w, h, t } = d;
  const top = h + TOP_EXTRA;
  p.moveTo(-w / 2 - t, top);
  if (outerR > 0) {
    p.lineTo(-w / 2 - t, -t + outerR);
    p.absarc(-w / 2 - t + outerR, -t + outerR, outerR, Math.PI, Math.PI * 1.5, false);
    p.lineTo(w / 2 + t - outerR, -t);
    p.absarc(w / 2 + t - outerR, -t + outerR, outerR, Math.PI * 1.5, Math.PI * 2, false);
  } else {
    p.lineTo(-w / 2 - t, -t);
    p.lineTo(w / 2 + t, -t);
  }
  p.lineTo(w / 2 + t, top);
  if (!close) return p;
  p.lineTo(w / 2, top);
  innerEdge(p, d, innerR, true);
  p.lineTo(-w / 2, top);
  return p;
}

/** inner boundary from top-right, down, across the floor, up to top-left (or the reverse) */
function innerEdge(p: THREE.Path, d: JarDims, r: number, fromRight: boolean) {
  const { w, h } = d;
  const top = h + TOP_EXTRA;
  if (fromRight) {
    p.lineTo(w / 2, r);
    if (r > 0) p.absarc(w / 2 - r, r, r, 0, -Math.PI / 2, true);
    p.lineTo(-w / 2 + r, 0);
    if (r > 0) p.absarc(-w / 2 + r, r, r, -Math.PI / 2, -Math.PI, true);
    p.lineTo(-w / 2, top);
  } else {
    p.moveTo(-w / 2, top);
    p.lineTo(-w / 2, r);
    if (r > 0) p.absarc(-w / 2 + r, r, r, Math.PI, Math.PI * 1.5, false);
    p.lineTo(w / 2 - r, 0);
    if (r > 0) p.absarc(w / 2 - r, r, r, Math.PI * 1.5, Math.PI * 2, false);
    p.lineTo(w / 2, top);
  }
}

function frameShape(d: JarDims, outerR: number, innerR: number) {
  return uPath(new THREE.Shape(), d, outerR, innerR, true) as THREE.Shape;
}

function line3(path: THREE.Path, z: number, divisions = 16) {
  return path.getPoints(divisions).map((p) => new THREE.Vector3(p.x, p.y, z));
}

function innerLine(d: JarDims, r: number, z: number) {
  const p = new THREE.Path();
  innerEdge(p, d, r, false);
  return line3(p, z);
}

function outerLine(d: JarDims, outerR: number, z: number) {
  return line3(uPath(new THREE.Path(), d, outerR, 0, false), z);
}

function tube(points: THREE.Vector3[], radius: number, mat: THREE.Material) {
  // dedupe consecutive points (paths repeat the joint between segments)
  const pts = points.filter((p, i) => i === 0 || p.distanceTo(points[i - 1]) > 1e-5);
  const curve = new THREE.CatmullRomCurve3(pts, false, 'catmullrom', 0.02);
  return new THREE.Mesh(
    new THREE.TubeGeometry(curve, Math.max(64, pts.length * 6), radius, 8, false),
    mat,
  );
}

const basic = (color: THREE.ColorRepresentation, opacity = 1, additive = false) =>
  new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1 || additive,
    opacity,
    depthWrite: !(opacity < 1 || additive),
    toneMapped: false,
    blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
  });

function extrude(
  shape: THREE.Shape,
  depth: number,
  bevel: number,
  mats: THREE.Material | THREE.Material[],
) {
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: depth - bevel * 2,
    bevelEnabled: bevel > 0,
    bevelThickness: bevel,
    bevelSize: bevel,
    bevelOffset: -bevel, // keeps the inner edge exactly on the boundary
    bevelSegments: 3,
    curveSegments: 16,
  });
  geo.translate(0, 0, bevel);
  const m = new THREE.Mesh(geo, mats);
  m.castShadow = m.receiveShadow = true;
  return m;
}

/**
 * Canvas covering the whole frame's front face. ExtrudeGeometry gives the caps world-space UVs,
 * so the texture is offset/scaled to map 1:1 onto the frame. `P` converts world -> canvas px.
 */
function frontCanvas(
  d: JarDims,
  pxPerUnit: number,
  draw: (
    g: CanvasRenderingContext2D,
    P: (x: number, y: number) => [number, number],
    s: number,
  ) => void,
) {
  const minX = -d.w / 2 - d.t;
  const maxX = d.w / 2 + d.t;
  const minY = -d.t;
  const maxY = d.h + TOP_EXTRA;
  const W = Math.round((maxX - minX) * pxPerUnit);
  const H = Math.round((maxY - minY) * pxPerUnit);
  const c = document.createElement('canvas');
  c.width = W;
  c.height = H;
  const g = c.getContext('2d')!;
  draw(g, (x, y) => [(x - minX) * pxPerUnit, (maxY - y) * pxPerUnit], pxPerUnit);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  tex.repeat.set(1 / (maxX - minX), 1 / (maxY - minY));
  tex.offset.set(-minX / (maxX - minX), -minY / (maxY - minY));
  return tex;
}

function textPlate(
  text: string,
  w: number,
  h: number,
  opts: { color?: string; glow?: string; font?: string; bg?: string } = {},
) {
  const c = document.createElement('canvas');
  c.width = 1024;
  c.height = Math.round((1024 * h) / w);
  const g = c.getContext('2d')!;
  if (opts.bg) {
    g.fillStyle = opts.bg;
    g.beginPath();
    g.roundRect(4, 4, c.width - 8, c.height - 8, c.height * 0.3);
    g.fill();
  }
  g.font = opts.font ?? `bold ${Math.round(c.height * 0.55)}px "Arial Black", Arial, sans-serif`;
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  if (opts.glow) {
    g.shadowColor = opts.glow;
    g.shadowBlur = c.height * 0.25;
  }
  g.fillStyle = opts.color ?? '#7dffbf';
  g.fillText(text, c.width / 2, c.height * 0.54);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  return new THREE.Mesh(
    new THREE.PlaneGeometry(w, h),
    new THREE.MeshBasicMaterial({
      map: tex,
      transparent: true,
      toneMapped: false,
      depthWrite: false,
    }),
  );
}

// ====================================================================== A. glass jar
function glassJar(d: JarDims): Jar {
  const { w, h, t, depth } = d;
  const group = new THREE.Group();
  const r = 0.34;
  const outerR = 0.5;
  const top = h + TOP_EXTRA;

  const glass = new THREE.MeshPhysicalMaterial({
    color: 0xd6fff0,
    roughness: 0.04,
    metalness: 0,
    transparent: true,
    opacity: 0.2,
    clearcoat: 1,
    clearcoatRoughness: 0.03,
    envMapIntensity: 2.2,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  const shell = extrude(frameShape(d, outerR, r), depth, 0.07, glass);
  shell.castShadow = false;
  group.add(shell);

  // crisp glass edges: bright on the front, faint at the back -> reads as thick glass
  const edgeFront = basic(0xffffff, 0.55);
  const edgeBack = basic(0xcffff0, 0.22);
  group.add(tube(innerLine(d, r, depth), 0.011, edgeFront));
  group.add(tube(outerLine(d, outerR, depth), 0.013, edgeFront));
  group.add(tube(innerLine(d, r, 0.01), 0.008, edgeBack));
  group.add(tube(outerLine(d, outerR, 0.01), 0.008, edgeBack));

  // vertical specular streaks on both walls
  const streakTex = (() => {
    const c = document.createElement('canvas');
    c.width = 16;
    c.height = 256;
    const g = c.getContext('2d')!;
    const gr = g.createLinearGradient(0, 0, 0, 256);
    gr.addColorStop(0, 'rgba(255,255,255,0)');
    gr.addColorStop(0.2, 'rgba(255,255,255,0.9)');
    gr.addColorStop(0.75, 'rgba(255,255,255,0.6)');
    gr.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = gr;
    g.fillRect(0, 0, 16, 256);
    const tx = new THREE.CanvasTexture(c);
    tx.colorSpace = THREE.SRGBColorSpace;
    return tx;
  })();
  const streak = (x: number, y0: number, y1: number, width: number, op: number) => {
    const m = new THREE.Mesh(
      new THREE.PlaneGeometry(width, y1 - y0),
      new THREE.MeshBasicMaterial({
        map: streakTex,
        transparent: true,
        opacity: op,
        depthWrite: false,
        toneMapped: false,
        blending: THREE.AdditiveBlending,
      }),
    );
    m.position.set(x, (y0 + y1) / 2, depth + 0.004);
    group.add(m);
  };
  streak(-w / 2 - t * 0.66, 0.9, h - 0.6, t * 0.2, 0.55);
  streak(-w / 2 - t * 0.36, 2.4, h - 2.2, t * 0.07, 0.4);
  streak(w / 2 + t * 0.4, 1.6, h - 1.4, t * 0.12, 0.35);

  // glass lips on top of the walls
  const lipMat = glass.clone();
  lipMat.opacity = 0.38;
  for (const sx of [-1, 1]) {
    const lip = new THREE.Mesh(
      new RoundedBoxGeometry(t + 0.12, 0.13, depth + 0.08, 4, 0.06),
      lipMat,
    );
    lip.position.set(sx * (w / 2 + t / 2), top + 0.02, depth / 2);
    group.add(lip);
    const shine = tube(
      [
        new THREE.Vector3(sx * (w / 2 + t / 2) - (t + 0.06) / 2, top + 0.07, depth + 0.03),
        new THREE.Vector3(sx * (w / 2 + t / 2) + (t + 0.06) / 2, top + 0.07, depth + 0.03),
      ],
      0.012,
      basic(0xffffff, 0.7),
    );
    group.add(shine);
  }

  // a faint reflection sheet across the opening (in front of the heads)
  const sheetTex = (() => {
    const c = document.createElement('canvas');
    c.width = 256;
    c.height = 360;
    const g = c.getContext('2d')!;
    const band = (x: number, wdt: number, a: number) => {
      g.save();
      g.translate(x, 0);
      g.rotate(-0.42);
      const gr = g.createLinearGradient(-wdt, 0, wdt, 0);
      gr.addColorStop(0, 'rgba(255,255,255,0)');
      gr.addColorStop(0.5, `rgba(255,255,255,${a})`);
      gr.addColorStop(1, 'rgba(255,255,255,0)');
      g.fillStyle = gr;
      g.fillRect(-wdt, -200, wdt * 2, 900);
      g.restore();
    };
    band(40, 34, 0.09);
    band(98, 10, 0.07);
    band(230, 22, 0.05);
    const tx = new THREE.CanvasTexture(c);
    tx.colorSpace = THREE.SRGBColorSpace;
    return tx;
  })();
  const sheet = new THREE.Mesh(
    new THREE.PlaneGeometry(w, h),
    new THREE.MeshBasicMaterial({
      map: sheetTex,
      transparent: true,
      depthWrite: false,
      toneMapped: false,
      blending: THREE.AdditiveBlending,
    }),
  );
  sheet.position.set(0, h / 2, depth - 0.02);
  sheet.renderOrder = 1e8;
  group.add(sheet);

  // dark stand with a glowing top edge
  const stand = new THREE.Mesh(
    new RoundedBoxGeometry(w + 2 * t + 0.36, 0.36, depth + 0.34, 4, 0.08),
    new THREE.MeshStandardMaterial({ color: 0x141c18, metalness: 0.6, roughness: 0.35 }),
  );
  stand.position.set(0, -t - 0.2, depth / 2);
  stand.receiveShadow = true;
  group.add(stand);
  group.add(
    tube(
      [
        new THREE.Vector3(-w / 2 - t - 0.1, -t - 0.02, depth + 0.18),
        new THREE.Vector3(w / 2 + t + 0.1, -t - 0.02, depth + 0.18),
      ],
      0.018,
      basic(GREEN),
    ),
  );
  const plate = textPlate('$SNEK  ·  MERGE', 2.8, 0.22, { glow: 'rgba(0,230,118,0.9)' });
  plate.position.set(0, -t - 0.2, depth + 0.175);
  group.add(plate);

  return { group, innerRadius: r, top: top + 0.1, update() {} };
}

// ====================================================================== B. trading terminal
// Everything on this frame reads from the live chart: title bar (pair, price, 24h change),
// the price axis on the right wall, the time axis on the base and the price tag.
function terminalJar(d: JarDims): Jar {
  const { w, h, t, dangerY } = d;
  const depth = 0.22;
  const group = new THREE.Group();
  const top = h + TOP_EXTRA;
  const mono = '"JetBrains Mono", "Consolas", "Menlo", monospace';
  const PX = 220; // canvas px per world unit

  const tex = frontCanvas(d, PX, (g, P, s) => {
    const [x0, y0] = P(-w / 2 - t, top);
    const [x1, y1] = P(w / 2 + t, -t);
    const bg = g.createLinearGradient(0, y0, 0, y1);
    bg.addColorStop(0, '#111a16');
    bg.addColorStop(1, '#0b110e');
    g.fillStyle = bg;
    g.fillRect(x0, y0, x1 - x0, y1 - y0);
    // left wall: decorative depth bars (not data)
    for (let y = 0.35; y < h - 0.2; y += 0.17) {
      const [ax, ay] = P(-w / 2 - t + 0.04, y);
      const len = (0.08 + Math.random() * 0.26) * s;
      g.fillStyle = y > h * 0.5 ? 'rgba(255,23,68,0.22)' : 'rgba(0,230,118,0.2)';
      g.fillRect(ax + (t * s - 0.08 * s - len), ay - 0.05 * s, len, 0.1 * s);
    }
    // borders: outer hairline + green inner edge + corner brackets
    g.strokeStyle = '#2c3d34';
    g.lineWidth = 3;
    g.strokeRect(x0 + 2, y0 + 2, x1 - x0 - 4, y1 - y0 - 4);
    const [ix0, iy0] = P(-w / 2, top);
    const [ix1, iy1] = P(w / 2, 0);
    g.strokeStyle = 'rgba(0,230,118,0.75)';
    g.beginPath();
    g.moveTo(ix0, iy0);
    g.lineTo(ix0, iy1);
    g.lineTo(ix1, iy1);
    g.lineTo(ix1, iy0);
    g.stroke();
    g.strokeStyle = GREEN;
    g.lineWidth = 6;
    const br = 0.22 * s;
    for (const [cx, cy, dx, dy] of [
      [x0 + 6, y1 - 6, 1, -1],
      [x1 - 6, y1 - 6, -1, -1],
    ] as const) {
      g.beginPath();
      g.moveTo(cx, cy + dy * br);
      g.lineTo(cx, cy);
      g.lineTo(cx + dx * br, cy);
      g.stroke();
    }
  });
  const capMat = new THREE.MeshStandardMaterial({ map: tex, roughness: 0.7, metalness: 0.1 });
  const sideMat = new THREE.MeshStandardMaterial({
    color: 0x0d1310,
    roughness: 0.6,
    metalness: 0.3,
  });
  group.add(extrude(frameShape(d, 0.12, 0), depth, 0.025, [capMat, sideMat]));

  // a canvas-backed plane we can redraw whenever the market changes
  const livePlane = (pw: number, ph: number, x: number, y: number, z: number) => {
    const c = document.createElement('canvas');
    c.width = Math.round(pw * PX);
    c.height = Math.round(ph * PX);
    const tx = new THREE.CanvasTexture(c);
    tx.colorSpace = THREE.SRGBColorSpace;
    tx.anisotropy = 8;
    const m = new THREE.Mesh(
      new THREE.PlaneGeometry(pw, ph),
      new THREE.MeshBasicMaterial({
        map: tx,
        transparent: true,
        depthWrite: false,
        toneMapped: false,
      }),
    );
    m.position.set(x, y, z);
    group.add(m);
    return { c, g: c.getContext('2d')!, tx, x0: x - pw / 2, y1: y + ph / 2 };
  };

  // window title bar across the top
  const barH = 0.62;
  const barShape = new THREE.Shape();
  const bx = w / 2 + t;
  const rr = 0.12;
  barShape.moveTo(-bx, top);
  barShape.lineTo(bx, top);
  barShape.lineTo(bx, top + barH - rr);
  barShape.absarc(bx - rr, top + barH - rr, rr, 0, Math.PI / 2, false);
  barShape.lineTo(-bx + rr, top + barH);
  barShape.absarc(-bx + rr, top + barH - rr, rr, Math.PI / 2, Math.PI, false);
  barShape.closePath();
  group.add(
    extrude(barShape, depth, 0.025, [
      new THREE.MeshStandardMaterial({ color: 0x16211c, roughness: 0.7, metalness: 0.1 }),
      sideMat,
    ]),
  );
  const bar = livePlane(2 * bx - 0.1, barH - 0.06, 0, top + barH / 2, depth + 0.003);
  const drawBar = (v: MarketView | null) => {
    const { c, g } = bar;
    const s = PX;
    g.clearRect(0, 0, c.width, c.height);
    g.fillStyle = 'rgba(0,230,118,0.8)';
    g.fillRect(0, c.height - 4, c.width, 4);
    const cy = c.height * 0.48;
    ['#ff5f57', '#febc2e', '#28c840'].forEach((col, i) => {
      g.fillStyle = col;
      g.beginPath();
      g.arc(0.2 * s + i * 0.17 * s, cy, 0.05 * s, 0, Math.PI * 2);
      g.fill();
    });
    g.textBaseline = 'middle';
    g.textAlign = 'left';
    g.fillStyle = '#eafff3';
    g.font = `800 ${Math.round(0.2 * s)}px ${mono}`;
    g.fillText('SNEK/USD', 0.78 * s, cy);
    g.fillStyle = '#1f3a2c';
    g.beginPath();
    g.roundRect(1.95 * s, cy - 0.11 * s, 0.42 * s, 0.22 * s, 0.05 * s);
    g.fill();
    g.fillStyle = '#69f0ae';
    g.font = `700 ${Math.round(0.13 * s)}px ${mono}`;
    g.textAlign = 'center';
    g.fillText(`${PERIOD_MIN}m`, 2.16 * s, cy + 1);
    // quote time: so players know exactly when this price is from
    if (v && v.quoteTime) {
      g.textAlign = 'left';
      const qx = 2.52 * s;
      g.fillStyle = v.status === 'offline' ? '#ffb300' : '#7f9f8f';
      g.font = `600 ${Math.round(0.1 * s)}px ${mono}`;
      g.fillText(quoteLabel(), qx, cy - 0.11 * s);
      g.fillStyle = v.status === 'offline' ? '#ffb300' : '#cfe9da';
      g.font = `700 ${Math.round(0.15 * s)}px ${mono}`;
      g.fillText(fmtClock(v.quoteTime), qx, cy + 0.08 * s);
    }
    g.textAlign = 'right';
    const right = c.width - 0.16 * s;
    if (v && v.change24h != null) {
      const ch = v.change24h;
      g.fillStyle = ch >= 0 ? GREEN : '#ff1744';
      g.font = `800 ${Math.round(0.18 * s)}px ${mono}`;
      const txt = `${ch >= 0 ? '+' : ''}${ch.toFixed(2)}%`;
      g.fillText(txt, right, cy);
      const cw = g.measureText(txt).width;
      if (v.price != null) {
        g.fillStyle = '#eafff3';
        g.font = `800 ${Math.round(0.17 * s)}px ${mono}`;
        g.fillText(`$${fmtPrice(v.price)}`, right - cw - 0.16 * s, cy);
      }
    } else {
      g.fillStyle = '#6f8a7b';
      g.font = `700 ${Math.round(0.15 * s)}px ${mono}`;
      g.fillText('…', right, cy);
    }
    bar.tx.needsUpdate = true;
  };
  drawBar(null);

  // price axis on the right wall, time axis on the base (both follow the live chart)
  const axis = livePlane(t, h, w / 2 + t / 2, h / 2, depth + 0.003);
  const times = livePlane(w, t, 0, -t / 2, depth + 0.003);

  // live price tag at the inner right edge + the liquidation tag on the red line
  const tagCanvas = document.createElement('canvas');
  tagCanvas.width = 300;
  tagCanvas.height = 72;
  const tagTex = new THREE.CanvasTexture(tagCanvas);
  tagTex.colorSpace = THREE.SRGBColorSpace;
  const drawTag = (v: number, up: boolean) => {
    const g = tagCanvas.getContext('2d')!;
    g.clearRect(0, 0, 300, 72);
    g.fillStyle = up ? '#00c853' : '#e53935';
    g.beginPath();
    g.moveTo(0, 36);
    g.lineTo(26, 4);
    g.lineTo(296, 4);
    g.lineTo(296, 68);
    g.lineTo(26, 68);
    g.closePath();
    g.fill();
    g.fillStyle = '#fff';
    g.font = `800 38px ${mono}`;
    g.textBaseline = 'middle';
    g.fillText(fmtPrice(v), 34, 38);
    tagTex.needsUpdate = true;
  };
  const tag = new THREE.Mesh(
    new THREE.PlaneGeometry(0.72, 0.175),
    new THREE.MeshBasicMaterial({
      map: tagTex,
      transparent: true,
      depthWrite: false,
      toneMapped: false,
    }),
  );
  tag.renderOrder = 1e7;
  tag.visible = false;
  group.add(tag);

  const liq = textPlate('爆倉 LIQ', 0.62, 0.17, {
    color: '#fff',
    bg: '#d50032',
    font: `800 120px ${mono}`,
  });
  liq.position.set(w / 2 - 0.33, dangerY, 0.008);
  liq.renderOrder = 1e7 + 1;
  group.add(liq);

  let seen = -1;
  let tagKey = '';
  return {
    group,
    innerRadius: 0,
    top: top + barH,
    update(_dt, { view, project }) {
      if (view.version !== seen) {
        seen = view.version;
        drawBar(view);
        // right wall: ticks projected from the back panel onto the wall's front face
        {
          const { c, g } = axis;
          g.clearRect(0, 0, c.width, c.height);
          g.font = `600 ${Math.round(0.085 * PX)}px ${mono}`;
          g.textBaseline = 'middle';
          for (const tk of view.ticks) {
            const y = project(w / 2, tk.y, depth).y;
            const py = (axis.y1 - y) * PX;
            if (py < 8 || py > c.height - 8) continue;
            g.strokeStyle = 'rgba(105,240,174,0.45)';
            g.lineWidth = 2;
            g.beginPath();
            g.moveTo(0, py);
            g.lineTo(0.05 * PX, py);
            g.stroke();
            g.fillStyle = '#8fb3a0';
            g.fillText(tk.label.replace(/^0\./, '.'), 0.07 * PX, py);
          }
          axis.tx.needsUpdate = true;
        }
        // base: time labels
        {
          const { c, g } = times;
          g.clearRect(0, 0, c.width, c.height);
          g.font = `600 ${Math.round(0.11 * PX)}px ${mono}`;
          g.textAlign = 'center';
          g.textBaseline = 'middle';
          for (const tt of view.timeTicks) {
            const x = project(tt.x, 0, depth).x;
            const px = (x - times.x0) * PX;
            if (px < 30 || px > c.width - 30) continue;
            g.fillStyle = '#7f9f8f';
            g.fillText(tt.label, px, c.height * 0.55);
            g.fillStyle = 'rgba(105,240,174,0.45)';
            g.fillRect(px - 1, 0, 2, 0.06 * PX);
          }
          times.tx.needsUpdate = true;
        }
      }
      // price tag follows the eased live price
      if (view.priceY != null && view.price != null) {
        const y = project(w / 2, view.priceY, 0.006).y;
        tag.visible = y > 0.1 && y < h;
        tag.position.set(w / 2 - 0.36, y, 0.006);
        const key = `${fmtPrice(view.price)}|${view.up}`;
        if (key !== tagKey) {
          tagKey = key;
          drawTag(view.price, view.up);
        }
      }
    },
  };
}

// ====================================================================== C. space capsule
function capsuleJar(d: JarDims): Jar {
  const { w, h, t, depth, dangerY } = d;
  const group = new THREE.Group();
  const r = 0.26;
  const outerR = 0.55;
  const top = h + TOP_EXTRA;

  const tex = frontCanvas(d, 200, (g, P, s) => {
    const [x0, y0] = P(-w / 2 - t, top);
    const [x1, y1] = P(w / 2 + t, -t);
    const bg = g.createLinearGradient(x0, 0, x1, 0);
    bg.addColorStop(0, '#59636f');
    bg.addColorStop(0.5, '#3d4651');
    bg.addColorStop(1, '#2c333c');
    g.fillStyle = bg;
    g.fillRect(x0, y0, x1 - x0, y1 - y0);
    // brushed metal grain
    for (let i = 0; i < 2200; i++) {
      g.fillStyle = `rgba(255,255,255,${Math.random() * 0.035})`;
      g.fillRect(
        x0 + Math.random() * (x1 - x0),
        y0 + Math.random() * (y1 - y0),
        1 + Math.random() * 30,
        1,
      );
    }

    // panel seams on both walls
    for (const xw of [-w / 2 - t, w / 2]) {
      for (let y = 1.4; y < h; y += 1.8) {
        const [ax, ay] = P(xw, y);
        g.fillStyle = 'rgba(0,0,0,0.55)';
        g.fillRect(ax, ay, t * s, 3);
        g.fillStyle = 'rgba(255,255,255,0.12)';
        g.fillRect(ax, ay + 3, t * s, 2);
      }
      // vents
      const [vx, vy] = P(xw + t * 0.22, h * 0.52);
      for (let i = 0; i < 5; i++) {
        g.fillStyle = '#15191e';
        g.beginPath();
        g.roundRect(vx, vy + i * 0.11 * s, t * 0.56 * s, 0.05 * s, 0.025 * s);
        g.fill();
        g.fillStyle = 'rgba(255,255,255,0.1)';
        g.fillRect(vx, vy + i * 0.11 * s + 0.05 * s, t * 0.56 * s, 2);
      }
      // danger level marker
      const [mx, my] = P(xw === w / 2 ? w / 2 + 0.02 : -w / 2 - 0.02, dangerY);
      const dir = xw === w / 2 ? 1 : -1;
      g.fillStyle = '#ff1744';
      g.beginPath();
      g.moveTo(mx, my);
      g.lineTo(mx + dir * 0.14 * s, my - 0.08 * s);
      g.lineTo(mx + dir * 0.14 * s, my + 0.08 * s);
      g.closePath();
      g.fill();
    }
    // stencil labels
    g.fillStyle = 'rgba(255,255,255,0.35)';
    g.font = `800 ${Math.round(0.1 * s)}px "Arial Black", Arial, sans-serif`;
    g.textAlign = 'center';
    g.save();
    const [lx, ly] = P(-w / 2 - t / 2, h - 1.0);
    g.translate(lx, ly);
    g.rotate(-Math.PI / 2);
    g.fillText('SNK-01', 0, 0);
    g.restore();
    g.save();
    const [rx, ry] = P(w / 2 + t / 2, h - 1.0);
    g.translate(rx, ry);
    g.rotate(Math.PI / 2);
    g.fillText('MOON BOUND', 0, 0);
    g.restore();

    // hazard stripes along the base
    const [hx0, hy0] = P(-w / 2 - t, 0);
    const [hx1, hy1] = P(w / 2 + t, -t);
    g.save();
    g.beginPath();
    g.rect(hx0, hy0 + 0.04 * s, hx1 - hx0, hy1 - hy0 - 0.04 * s);
    g.clip();
    g.fillStyle = '#ffc400';
    g.fillRect(hx0, hy0, hx1 - hx0, hy1 - hy0);
    g.fillStyle = '#16181c';
    const sw = 0.16 * s;
    for (let x = hx0 - (hy1 - hy0); x < hx1; x += sw * 2) {
      g.beginPath();
      g.moveTo(x, hy1);
      g.lineTo(x + sw, hy1);
      g.lineTo(x + sw + (hy1 - hy0), hy0);
      g.lineTo(x + (hy1 - hy0), hy0);
      g.closePath();
      g.fill();
    }
    g.restore();
    // name plate over the stripes
    const pw = 2.7 * s;
    const ph = 0.26 * s;
    const pcx = (hx0 + hx1) / 2;
    const pcy = (hy0 + hy1) / 2 + 0.02 * s;
    g.fillStyle = '#0f1418';
    g.strokeStyle = '#7d8996';
    g.lineWidth = 4;
    g.beginPath();
    g.roundRect(pcx - pw / 2, pcy - ph / 2, pw, ph, ph * 0.3);
    g.fill();
    g.stroke();
    g.shadowColor = 'rgba(0,230,118,0.9)';
    g.shadowBlur = 14;
    g.fillStyle = '#7dffbf';
    g.font = `900 ${Math.round(ph * 0.58)}px "Arial Black", Arial, sans-serif`;
    g.textBaseline = 'middle';
    g.fillText('$SNEK  ·  MERGE', pcx, pcy + 2);
    g.shadowBlur = 0;
  });
  const capMat = new THREE.MeshStandardMaterial({ map: tex, metalness: 0.7, roughness: 0.42 });
  const sideMat = new THREE.MeshStandardMaterial({
    color: 0x2a3038,
    metalness: 0.85,
    roughness: 0.3,
  });
  group.add(extrude(frameShape(d, outerR, r), depth, 0.06, [capMat, sideMat]));

  // rivets
  const rivetGeo = new THREE.SphereGeometry(0.028, 12, 8, 0, Math.PI * 2, 0, Math.PI / 2);
  rivetGeo.rotateX(Math.PI / 2);
  const rivetPos: THREE.Vector3[] = [];
  for (const x of [-w / 2 - t * 0.5, w / 2 + t * 0.5]) {
    for (let y = 0.5; y < h; y += 0.6) {
      if (Math.abs(y - h * 0.52 - 0.22) < 0.45) continue; // skip the vents
      rivetPos.push(
        new THREE.Vector3(x - t * 0.28, y, depth),
        new THREE.Vector3(x + t * 0.28, y, depth),
      );
    }
  }
  const rivets = new THREE.InstancedMesh(
    rivetGeo,
    new THREE.MeshStandardMaterial({ color: 0xaab4c0, metalness: 0.9, roughness: 0.25 }),
    rivetPos.length,
  );
  rivetPos.forEach((p, i) =>
    rivets.setMatrixAt(i, new THREE.Matrix4().makeTranslation(p.x, p.y, p.z)),
  );
  group.add(rivets);

  // inner glow strip + soft halo
  group.add(tube(innerLine(d, r, 0.014), 0.016, basic(0x3dffc0)));
  group.add(tube(innerLine(d, r, 0.014), 0.06, basic(0x3dffc0, 0.16, true)));
  // front rim highlight
  group.add(tube(outerLine(d, outerR, depth + 0.004), 0.01, basic(0xd8e4f0, 0.35)));

  // status lamps on top of the walls
  const lamps: THREE.Mesh<THREE.CylinderGeometry, THREE.MeshBasicMaterial>[] = [];
  for (const sx of [-1, 1]) {
    const base = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.13, 0.08, 20), sideMat);
    base.position.set(sx * (w / 2 + t / 2), top + 0.04, depth * 0.55);
    const lamp = new THREE.Mesh(
      new THREE.CylinderGeometry(0.075, 0.075, 0.07, 20),
      basic(0x00e676),
    );
    lamp.position.set(sx * (w / 2 + t / 2), top + 0.1, depth * 0.55);
    lamps.push(lamp);
    group.add(base, lamp);
  }
  let time = 0;
  return {
    group,
    innerRadius: r,
    top: top + 0.15,
    update(dt) {
      time += dt;
      lamps.forEach((l, i) => {
        const on = Math.sin(time * 3 + i * Math.PI) > 0;
        l.material.color.setHex(on ? 0x00e676 : 0x0b3d24);
      });
    },
  };
}

// ====================================================================== D. neon (original)
function neonJar(d: JarDims): Jar {
  const { w, t, depth } = d;
  const group = new THREE.Group();
  const top = d.h + TOP_EXTRA;
  const frameMat = new THREE.MeshStandardMaterial({
    color: 0x1e2b25,
    roughness: 0.38,
    metalness: 0.55,
  });
  group.add(extrude(frameShape(d, 0.32, 0), depth, 0.05, frameMat));
  group.add(tube(innerLine(d, 0, 0.012), 0.022, basic(GREEN)));
  group.add(tube(innerLine(d, 0, 0.012), 0.075, basic(GREEN, 0.18, true)));
  group.add(tube(outerLine(d, 0.32, depth + 0.005), 0.012, basic(0x3dffa0, 0.55)));
  for (const sx of [-1, 1]) {
    const cap = new THREE.Mesh(new THREE.BoxGeometry(t * 0.55, 0.05, 0.05), basic(GREEN));
    cap.position.set(sx * (w / 2 + t / 2), top + 0.03, depth * 0.6);
    group.add(cap);
  }
  const plate = textPlate('$SNEK  ·  MERGE', w * 0.62, t * 0.62, { glow: 'rgba(0,230,118,0.9)' });
  plate.position.set(0, -t / 2, depth + 0.006);
  group.add(plate);
  return { group, innerRadius: 0, top: top + 0.06, update() {} };
}
