import { AnalyticsService } from '../../platform/AnalyticsService.ts';

// ---------------------------------------------------------------- storage
const KEY = 'snek-merge:';
const store = {
  get(k: string): string | null {
    try {
      return localStorage.getItem(KEY + k);
    } catch {
      return null;
    }
  },
  set(k: string, v: string | number) {
    try {
      localStorage.setItem(KEY + k, String(v));
    } catch {
      /* private mode etc. */
    }
  },
};

// Same keys as the arcade lobby's I18nService, so the language follows the player between the two
const ARCADE_LOCALE_KEYS = ['snek_locale', 'snek_arcade:locale', 'snek_lang'];
function readArcadeLocale(): string | null {
  try {
    for (const k of ARCADE_LOCALE_KEYS) {
      const v = localStorage.getItem(k);
      if (v) return v;
    }
  } catch {
    /* storage blocked */
  }
  return null;
}
function saveLang(l: Lang) {
  store.set('lang', l);
  try {
    for (const k of ARCADE_LOCALE_KEYS) localStorage.setItem(k, arcadeLocale(l));
  } catch {
    /* storage blocked */
  }
}

let lang: Lang = detectLang([
  new URLSearchParams(location.search).get('lang'),
  readArcadeLocale(),
  store.get('lang'),
]);
let t = dict(lang);
let best = Number(store.get('best')) || 0;
let everMax = Number(store.get('maxLevel')) || 0;
// jar frame theme: ?frame= in the URL wins (handy for sharing), then the saved choice
const urlFrame = new URLSearchParams(location.search).get('frame') as FrameStyle | null;
const savedFrame = store.get('frame') as FrameStyle | null;
let theme: FrameStyle =
  [urlFrame, savedFrame].find((f): f is FrameStyle => !!f && FRAME_STYLES.includes(f)) ??
  DEFAULT_FRAME;
let onTheme: (f: FrameStyle) => void = () => {};

function renderPickers() {
  document.querySelectorAll<HTMLElement>('[data-picker]').forEach((el) => {
    el.innerHTML = `<div class="lbl">${t.theme}</div><div class="themes">${FRAME_STYLES.map(
      (f) =>
        `<button class="th ${f === theme ? 'on' : ''}" data-frame="${f}" aria-pressed="${f === theme}"><i class="sw sw-${f}"></i><span>${t.themes[f]}</span></button>`,
    ).join('')}</div>`;
  });
}
document.addEventListener('click', (e) => {
  const b = (e.target as HTMLElement).closest<HTMLElement>('[data-frame]');
  if (!b) return;
  theme = b.dataset.frame as FrameStyle;
  store.set('frame', theme);
  renderPickers();
  onTheme(theme);
});

const sfx = new Sfx();
sfx.muted = store.get('muted') === '1';

const icons = HEAD_STYLES.map(
  (s) => `data:image/svg+xml;charset=utf-8,${encodeURIComponent(headSvg(s))}`,
);
const iconUrl = (level: number) => icons[level];

