const $ = <T extends HTMLElement = HTMLElement>(id: string) => document.getElementById(id) as T;
const scoreEl = $('score');
const bestEl = $('best');
const nextImg = $<HTMLImageElement>('next');
const vignette = $('vignette');
const fx = $('fx');
const toast = $('toast');
const chain = $('chain');

function show(id: string, on: boolean) {
  $(id).classList.toggle('hidden', !on);
}

function applyLang() {
  t = dict(lang);
  document.documentElement.lang = lang;
  document.querySelectorAll<HTMLElement>('[data-t]').forEach((el) => {
    const v = (t as unknown as Record<string, unknown>)[el.dataset.t!];
    if (typeof v === 'string') el.textContent = v;
  });
  $('howto').innerHTML = t.howTo.map((s) => `<li>${s}</li>`).join('');
  renderPickers();
  $('lang').textContent = LANG_LABEL[lang];
  buildChain();
}

function buildChain() {
  const items = LEVELS.map((_, i) => {
    const locked = i > everMax && i > 4;
    return `<div class="chip ${locked ? 'locked' : ''} ${i === MAX_LEVEL ? 'gold' : ''}" data-l="${i}" title="${t.pets[LEVELS[i].id]}">
      <img src="${iconUrl(i)}" alt="" />
    </div>`;
  }).join('<span class="arrow">›</span>');
  chain.innerHTML = items;
  $('chainPreview').innerHTML = LEVELS.map(
    (_, i) =>
      `<div class="pv ${i === MAX_LEVEL ? 'gold' : ''}"><img src="${iconUrl(i)}" alt="" /><span>${t.pets[LEVELS[i].id]}</span></div>`,
  ).join('');
}

function highlightChain(level: number) {
  const chip = chain.querySelector<HTMLElement>(`[data-l="${level}"]`);
  if (!chip) return;
  chip.classList.remove('locked', 'flash');
  void chip.offsetWidth;
  chip.classList.add('flash');
}

function setMuteIcon() {
  $('mute').textContent = sfx.muted ? '🔇' : '🔊';
}

function floatText(text: string, x: number, y: number, cls = '') {
  const el = document.createElement('div');
  el.className = `float ${cls}`;
  el.textContent = text;
  el.style.left = `${x}px`;
  el.style.top = `${y}px`;
  fx.appendChild(el);
  setTimeout(() => el.remove(), 1200);
}

let toastTimer = 0;
function showToast(html: string, cls = '') {
  toast.innerHTML = html;
  toast.className = `toast show ${cls}`;
  clearTimeout(toastTimer);
  toastTimer = window.setTimeout(() => (toast.className = 'toast'), 2200);
}

// ---------------------------------------------------------------- big moments (margin call, liquidation, moon)
const alarmEl = $('alarm');
const marginCall = $('marginCall');
const cracksEl = $('cracks');
const confettiEl = $('confetti');

function flashScreen(kind: 'red' | 'gold' | 'white') {
  const el = $('flash');
  el.className = `screen-flash ${kind}`;
  void el.offsetWidth;
  el.classList.add('go');
}

function setDangerUi(amount: number) {
  const on = amount > 0;
  document.body.classList.toggle('in-danger', on);
  document.body.classList.toggle('critical', amount > 0.6);
  // the alarm blinks faster the closer we are to liquidation
  alarmEl.style.setProperty('--speed', `${(0.9 - Math.min(1, amount) * 0.62).toFixed(2)}s`);
  marginCall.classList.toggle('show', on);
  if (on) {
    // like an exchange's margin ratio (保證金率): it climbs while a head stays over the line, 100% = closed out.
    // After the moon shot the run is already won, so the same meter is a trailing take-profit instead.
    const won = game.hasWon;
    const a = Math.min(1, amount);
    const ratio = 60 + 40 * a;
    marginCall.classList.toggle('tp', won);
    document.body.classList.toggle('won-run', won);
    $('mcTitle').textContent = won ? t.warnTitleWon : t.warnTitle;
    $('mcLabel').textContent = won ? t.ratioWon : t.ratio;
    $('mcSub').textContent = won ? t.warnSubWon : t.warnSub;
    $('mcRatio').textContent = `${ratio.toFixed(1)}%`;
    $('mcBar').style.width = `${ratio}%`;
  }
}

/** glass cracks spreading from where the jar burst */
function drawCracks(at: ScreenPos) {
  const w = window.innerWidth;
  const h = window.innerHeight;
  const R = Math.hypot(w, h);
  const pt = (x: number, y: number) => `${x.toFixed(0)},${y.toFixed(0)}`;
  let paths = '';
  const n = 12;
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2 + Math.random() * 0.45;
    let x = at.x;
    let y = at.y;
    let d = `M${pt(x, y)}`;
    const len = R * (0.3 + Math.random() * 0.45);
    for (let walked = 0; walked < len; ) {
      const step = 22 + Math.random() * 60;
      a += (Math.random() - 0.5) * 0.55;
      x += Math.cos(a) * step;
      y += Math.sin(a) * step;
      walked += step;
      d += ` L${pt(x, y)}`;
      if (Math.random() < 0.16) {
        // a side branch
        let bx = x;
        let by = y;
        let ba = a + (Math.random() < 0.5 ? -1 : 1) * (0.5 + Math.random() * 0.6);
        let bd = `M${pt(bx, by)}`;
        for (let k = 0; k < 2 + Math.random() * 3; k++) {
          const s = 15 + Math.random() * 35;
          ba += (Math.random() - 0.5) * 0.6;
          bx += Math.cos(ba) * s;
          by += Math.sin(ba) * s;
          bd += ` L${pt(bx, by)}`;
        }
        paths += `<path class="br" d="${bd}" pathLength="1" style="animation-delay:${(0.1 + Math.random() * 0.15).toFixed(2)}s"/>`;
      }
    }
    paths += `<path d="${d}" pathLength="1" style="animation-delay:${(Math.random() * 0.06).toFixed(2)}s"/>`;
  }
  // broken rings around the impact
  for (const r of [34, 80, 150]) {
    let d = '';
    const seg = 14;
    for (let i = 0; i < seg; i++) {
      if (Math.random() < 0.35) continue;
      const a0 = (i / seg) * Math.PI * 2;
      const a1 = ((i + 1) / seg) * Math.PI * 2;
      const j = () => r * (0.85 + Math.random() * 0.3);
      d += `M${pt(at.x + Math.cos(a0) * j(), at.y + Math.sin(a0) * j())} L${pt(at.x + Math.cos(a1) * j(), at.y + Math.sin(a1) * j())} `;
    }
    if (d)
      paths += `<path class="ring" d="${d}" pathLength="1" style="animation-delay:${(r / 600).toFixed(2)}s"/>`;
  }
  cracksEl.innerHTML = `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><circle cx="${at.x}" cy="${at.y}" r="10" class="impact"/>${paths}</svg>`;
  cracksEl.classList.add('show');
}

function confetti(n: number, layer: HTMLElement = confettiEl) {
  const colors = ['#ffea00', '#00e676', '#ff84bf', '#8bcfff', '#ffffff', '#ff9f48', '#ffc400'];
  for (let i = 0; i < n; i++) {
    const el = document.createElement('i');
    el.className = 'confetti';
    el.style.left = `${Math.random() * 100}%`;
    el.style.background = colors[i % colors.length];
    el.style.width = `${5 + Math.random() * 5}px`;
    el.style.height = `${9 + Math.random() * 8}px`;
    el.style.setProperty('--dx', `${((Math.random() - 0.5) * 220).toFixed(0)}px`);
    el.style.setProperty('--r', `${(Math.random() * 1440 - 720).toFixed(0)}deg`);
    el.style.animationDuration = `${(2.4 + Math.random() * 2).toFixed(2)}s`;
    el.style.animationDelay = `${(Math.random() * 0.8).toFixed(2)}s`;
    layer.appendChild(el);
    setTimeout(() => el.remove(), 5500);
  }
}

function moonBanner() {
  const el = document.createElement('div');
  el.className = 'moon-banner';
  el.innerHTML = `<span>🚀</span><b>TO THE MOON</b><span>🌕</span>`;
  fx.appendChild(el);
  setTimeout(() => el.remove(), 2600);
}

function countUp(el: HTMLElement, to: number, ms = 900) {
  const t0 = performance.now();
  const step = (now: number) => {
    const k = Math.min(1, (now - t0) / ms);
    el.textContent = Math.round(to * (1 - (1 - k) ** 3)).toLocaleString();
    if (k < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

const fmtTime = (ms: number) => {
  const s = Math.max(0, Math.floor(ms / 1000));
  return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
};

function saveBest(s: number) {
  const isRecord = s > best;
  if (isRecord) {
    best = s;
    store.set('best', best);
  }
  bestEl.textContent = best.toLocaleString();
  bestEl.parentElement!.classList.remove('beating');
  return isRecord;
}

function clearMoments() {
  setDangerUi(0);
  vignette.style.opacity = '0';
  cracksEl.classList.remove('show');
  cracksEl.innerHTML = '';
  document.body.classList.remove('liquidating', 'won-run');
  $('stamp').classList.remove('slam');
  confettiEl.innerHTML = '';
}

function measureInsets() {
  const top = document.querySelector('.hud-top')!.getBoundingClientRect().bottom + 6;
  const bottom = window.innerHeight - chain.getBoundingClientRect().top + 6;
  return { top, bottom };
}

// ---------------------------------------------------------------- game
AnalyticsService.trackPageView('/merge', 'SNEK Merge 蛇蛇合成');
applyLang();
setMuteIcon();
bestEl.textContent = best.toLocaleString();

let lastWarnAt = 0;
/** worst danger reached since the last time we were safe (for the "phew" toast) */
let dangerPeak = 0;
const game = await Game.load(
  $('stage'),
  {
    score(total, gained, at, combo) {
      scoreEl.textContent = total.toLocaleString();
      if (gained > 0) {
        floatText(`+${gained}`, at.x, at.y, gained >= 100 ? 'big' : '');
        if (combo >= 2) floatText(fmt(t.combo, { n: combo }), at.x, at.y - 34, 'combo');
      }
      if (total > best) {
        bestEl.textContent = total.toLocaleString();
        bestEl.parentElement!.classList.add('beating');
      }
    },
    merged(level, combo) {
      sfx.merge(level, combo);
      if (level > everMax) {
        everMax = level;
        store.set('maxLevel', everMax);
        highlightChain(level);
        sfx.unlockNew();
        showToast(
          `<img src="${iconUrl(level)}" alt="" /> ${fmt(t.unlocked, { name: t.pets[LEVELS[level].id] })}`,
          level === MAX_LEVEL ? 'gold' : '',
        );
      }
    },
    next(level) {
      nextImg.src = iconUrl(level);
      nextImg.classList.remove('pop');
      void nextImg.offsetWidth;
      nextImg.classList.add('pop');
    },
    danger(amount) {
      vignette.style.opacity = String(Math.min(1, amount * 1.2));
      setDangerUi(amount);
      if (amount > 0) dangerPeak = Math.max(dangerPeak, amount);
      else {
        if (dangerPeak > 0.3 && game.state === 'playing')
          showToast(`✅ ${game.hasWon ? t.safeWon : t.safe}`);
        dangerPeak = 0;
      }
      const now = performance.now();
      if (amount > 0.25 && game.state === 'playing' && now - lastWarnAt > 600 - amount * 300) {
        lastWarnAt = now;
        sfx.warn();
      }
    },
    alarm() {
      if (game.hasWon) {
        // already on the moon: this is a take-profit, no siren
        sfx.unlockNew();
        flashScreen('gold');
        return;
      }
      sfx.siren();
      flashScreen('red');
      document.body.classList.add('liquidating');
    },
    liquidate(at) {
      setDangerUi(0);
      if (game.hasWon) {
        sfx.cashOut();
        flashScreen('gold');
        confetti(70, fx);
        vignette.style.opacity = '0';
        return;
      }
      sfx.boom();
      flashScreen('white');
      drawCracks(at);
      vignette.style.opacity = '1';
    },
    over() {
      const won = game.hasWon;
      if (!won) sfx.gameOver();
      document.body.classList.remove('liquidating');
      // a run that already reached the moon ends with a take-profit notice, not a liquidation
      $('slip').classList.toggle('tp', won);
      $('overScreen').classList.toggle('tp', won);
      $('slipTitle').textContent = won ? t.tpTitle : t.liqTitle;
      $('slipKind').textContent = won ? 'TAKE PROFIT NOTICE' : 'LIQUIDATION NOTICE';
      $('stampBig').textContent = won ? 'PROFIT' : 'REKT';
      $('stampSmall').textContent = won ? t.tpStampSub : t.stampSub;
      $('atLbl').textContent = won ? t.tpAt : t.liqAt;
      show('moonRow', won);
      $('moonTime').textContent = fmtTime(game.winMs);
      const s = game.score;
      const isRecord = saveBest(s);
      $('finalScore').textContent = '0';
      countUp($('finalScore'), s);
      show('newRecord', isRecord && s > 0);
      const hl = game.bestLevelThisRun;
      AnalyticsService.trackGameOver({
        game_id: 'merge',
        score: s,
        level: hl,
        duration_sec: Math.round(game.elapsedMs / 1000),
        reason: won ? 'take_profit' : 'liquidated',
      });
      $<HTMLImageElement>('highestImg').src = iconUrl(hl);
      $('highestName').textContent = t.pets[LEVELS[hl].id];
      $('liqSurvive').textContent = fmtTime(game.elapsedMs);
      const d = new Date();
      $('liqAt').textContent = `${d.getMonth() + 1}/${d.getDate()} ${fmtClock(d.getTime())}`;
      $('slipNo').textContent = String(Math.floor(10_000_000 + Math.random() * 89_999_999));
      show('overScreen', true);
      // the REKT stamp slams onto the notice
      const stamp = $('stamp');
      stamp.classList.remove('slam');
      void stamp.offsetWidth;
      stamp.classList.add('slam');
      setTimeout(() => sfx.stamp(), 560);
      if (won) {
        setTimeout(() => sfx.fanfare(), 750);
        confetti(90);
      }
    },
    moon(at, first) {
      sfx.moon();
      if (!first) floatText(t.moon, at.x, at.y - 40, 'moon');
      if (first) {
        dangerPeak = 0;
        flashScreen('gold');
        moonBanner();
        confetti(60, fx);
      } else showToast(`🚀 ${t.moon}`, 'gold');
    },
    won() {
      sfx.fanfare();
      saveBest(game.score);
      const ms = game.winMs;
      const prev = Number(store.get('fastMoon')) || 0;
      const fastest = !prev || ms < prev;
      if (fastest) store.set('fastMoon', Math.round(ms));
      $<HTMLImageElement>('winImg').src = iconUrl(MAX_LEVEL);
      $('winScore').textContent = '0';
      countUp($('winScore'), game.score);
      $('winTime').textContent = fmtTime(ms);
      $('winFast').textContent = fastest ? fmtTime(ms) : prev ? fmtTime(prev) : '—';
      show('fastRecord', fastest && !!prev);
      show('winScreen', true);
      confetti(120);
    },
    firework() {
      sfx.firework();
    },
  },
  (p) => {
    $('loadFill').style.width = `${Math.round(p * 100)}%`;
  },
  theme,
);
onTheme = (f) => game.setFrame(f);
game.sfxDrop = () => sfx.drop();
game.sfxThud = (speed) => sfx.thud(speed);

const fitInsets = () => {
  const { top, bottom } = measureInsets();
  game.setInsets(top, bottom);
};
fitInsets();
window.addEventListener('resize', fitInsets);

show('loading', false);
show('startScreen', true);

function startGame() {
  sfx.unlock();
  show('startScreen', false);
  show('overScreen', false);
  show('pauseScreen', false);
  show('winScreen', false);
  clearMoments();
  dangerPeak = 0;
  game.start();
  AnalyticsService.trackGameStart('merge');
}

function continueRun() {
  show('winScreen', false);
  confettiEl.innerHTML = '';
  game.continueRun();
}

function togglePause(force?: boolean) {
  const wantPause = force ?? game.state === 'playing';
  if (wantPause && game.state === 'playing') {
    game.pause();
    show('pauseScreen', true);
  } else if (!wantPause && game.state === 'paused') {
    show('pauseScreen', false);
    game.resume();
  }
}

// ---------------------------------------------------------------- input
const canvas = document.querySelector<HTMLCanvasElement>('.game-canvas')!;
let pressing = false;
canvas.addEventListener('pointerdown', (e) => {
  if (game.state !== 'playing') return;
  sfx.unlock();
  pressing = true;
  canvas.setPointerCapture(e.pointerId);
  game.aimAtClient(e.clientX, e.clientY);
});
canvas.addEventListener('pointermove', (e) => {
  if (game.state !== 'playing') return;
  if (pressing || e.pointerType === 'mouse') game.aimAtClient(e.clientX, e.clientY);
});
canvas.addEventListener('pointerup', (e) => {
  if (!pressing) return;
  pressing = false;
  game.aimAtClient(e.clientX, e.clientY);
  game.drop();
});
canvas.addEventListener('pointercancel', () => (pressing = false));

window.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowLeft' || e.key === 'a') game.setKey('left', true);
  else if (e.key === 'ArrowRight' || e.key === 'd') game.setKey('right', true);
  else if (e.key === ' ' || e.key === 'ArrowDown' || e.key === 'Enter') {
    e.preventDefault();
    if (game.state === 'playing') game.drop();
    else if (game.state === 'won') continueRun();
    else if (
      game.state === 'ready' ||
      (game.state === 'over' && !$('overScreen').classList.contains('hidden'))
    )
      startGame();
  } else if (e.key === 'Escape' || e.key === 'p') togglePause();
});
window.addEventListener('keyup', (e) => {
  if (e.key === 'ArrowLeft' || e.key === 'a') game.setKey('left', false);
  else if (e.key === 'ArrowRight' || e.key === 'd') game.setKey('right', false);
});

document.addEventListener('visibilitychange', () => {
  if (document.hidden) togglePause(true);
});

$('startBtn').addEventListener('click', startGame);
$('againBtn').addEventListener('click', startGame);
$('restartBtn').addEventListener('click', startGame);
$('resumeBtn').addEventListener('click', () => togglePause(false));
$('pauseBtn').addEventListener('click', () => togglePause());
$('mute').addEventListener('click', () => {
  sfx.muted = !sfx.muted;
  store.set('muted', sfx.muted ? '1' : '0');
  sfx.unlock();
  setMuteIcon();
});
$('lang').addEventListener('click', () => {
  lang = LANGS[(LANGS.indexOf(lang) + 1) % LANGS.length];
  saveLang(lang);
  applyLang();
  fitInsets();
});
$('continueBtn').addEventListener('click', continueRun);
$('winShareBtn').addEventListener('click', () => {
  const text = fmt(t.winShareText, {
    score: game.score.toLocaleString(),
    time: fmtTime(game.winMs),
  });
  const url = `https://x.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(GAME_URL)}`;
  window.open(url, '_blank', 'noopener');
});
$('shareBtn').addEventListener('click', () => {
  const text = game.hasWon
    ? fmt(t.winShareText, { score: game.score.toLocaleString(), time: fmtTime(game.winMs) })
    : fmt(t.shareText, {
        score: game.score.toLocaleString(),
        name: t.pets[LEVELS[game.bestLevelThisRun].id],
      });
  const url = `https://x.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(GAME_URL)}`;
  window.open(url, '_blank', 'noopener');
});
