// The moon behind the jar. Its surface is computed per pixel on the GPU (no texture):
// maria, three layers of craters with real bowls and rims, ray systems from a couple of
// young craters, lunar-style shading with a soft terminator and faint earthshine.
// Because everything is evaluated on the sphere it stays sharp at any size and has no seams.
// It also places itself where the sky is visible (beside the jar on wide screens,
// in the strip above the jar on phones) and slowly spins.
import * as THREE from 'three';

const MOON_Z = -10;
const SPIN = 0.05; // rad/s, about two minutes per turn
/** sunlight direction in *camera* space: from the upper left, slightly in front -> waxing gibbous */
const LIGHT_VIEW = new THREE.Vector3(-0.72, 0.36, 0.6).normalize();

export class Moon {
  root = new THREE.Group();
  private mesh: THREE.Mesh<THREE.SphereGeometry, THREE.ShaderMaterial>;
  private halo: THREE.Sprite;
  private glow = 0;
  private ray = new THREE.Raycaster();
  private q = new THREE.Quaternion();
  private v = new THREE.Vector3();

  constructor() {
    this.mesh = new THREE.Mesh(new THREE.SphereGeometry(1, 128, 96), makeMoonMaterial());
    // a slight axial tilt so the spin reads as a real rotation, not a slide
    this.mesh.rotation.set(0.32, 0.6, 0.1);
    this.halo = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: haloTexture(),
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        fog: false,
        toneMapped: false,
      }),
    );
    this.halo.scale.setScalar(3.2);
    this.halo.position.z = -0.6;
    this.halo.renderOrder = -1;
    this.root.add(this.halo, this.mesh);
    this.root.position.set(5.6, 11.2, MOON_Z);
  }

  get position() {
    return this.root.position;
  }

  /** brighten after a moonshot */
  flash() {
    this.glow = 1;
  }

  update(dt: number, camera: THREE.Camera) {
    this.glow = Math.max(0, this.glow - dt * 0.6);
    this.mesh.rotation.y += dt * SPIN;
    this.halo.material.opacity = 0.5 + this.glow * 0.5;
    this.halo.scale.setScalar(3.2 + this.glow * 1.3);

    // lighting is done in the moon's own space so the craters stay put while it spins
    this.mesh.updateWorldMatrix(true, false);
    const u = this.mesh.material.uniforms;
    const toLocal = this.mesh.getWorldQuaternion(this.q).invert();
    u.uLight.value
      .copy(LIGHT_VIEW)
      .applyQuaternion(camera.quaternion)
      .applyQuaternion(toLocal)
      .normalize();
    u.uView.value.copy(this.mesh.worldToLocal(this.v.copy(camera.position)));
    u.uGlow.value = this.glow;
  }

  /**
   * @param jarRightNdc  NDC x of the jar's outer right edge
   * @param band         NDC y band of open sky between jar top and HUD
   */
  place(
    camera: THREE.PerspectiveCamera,
    widthPx: number,
    heightPx: number,
    jarRightNdc: number,
    band: [number, number],
  ) {
    const sidePx = ((1 - jarRightNdc) / 2) * widthPx;
    let ndcX: number;
    let ndcY: number;
    let radiusPx: number;
    if (sidePx > 170) {
      // wide screen: sit in the empty space to the right of the jar
      radiusPx = Math.min(sidePx * 0.3, heightPx * 0.13);
      ndcX = jarRightNdc + (1 - jarRightNdc) * 0.5;
      ndcY = 0.42;
    } else {
      // phone: the strip of sky between the HUD and the jar, right side
      const bandPx = (Math.max(0.05, band[1] - band[0]) / 2) * heightPx;
      radiusPx = THREE.MathUtils.clamp(bandPx * 0.4, 24, 64);
      ndcX = 1 - (2 * (radiusPx + 22)) / widthPx;
      ndcY = (band[0] + band[1]) / 2;
    }
    this.ray.setFromCamera(new THREE.Vector2(ndcX, ndcY), camera);
    const hit = new THREE.Vector3();
    if (!this.ray.ray.intersectPlane(new THREE.Plane(new THREE.Vector3(0, 0, 1), -MOON_Z), hit))
      return;
    const dist = hit.distanceTo(camera.position);
    const worldPerPx = (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)) * dist) / heightPx;
    this.root.position.copy(hit);
    this.root.scale.setScalar(radiusPx * worldPerPx);
  }
}

// ---------------------------------------------------------------- surface shader
function makeMoonMaterial() {
  return new THREE.ShaderMaterial({
    uniforms: {
      uLight: { value: new THREE.Vector3(-0.6, 0.4, 0.7).normalize() },
      uView: { value: new THREE.Vector3(0, 0, 10) },
      uGlow: { value: 0 },
    },
    vertexShader: /* glsl */ `
      varying vec3 vPos;
      void main() {
        vPos = position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }`,
    fragmentShader: /* glsl */ `
      uniform vec3 uLight;
      uniform vec3 uView;
      uniform float uGlow;
      varying vec3 vPos;

      vec3 hash33(vec3 p) {
        p = fract(p * vec3(0.1031, 0.1030, 0.0973));
        p += dot(p, p.yxz + 33.33);
        return fract((p.xxy + p.yxx) * p.zyx);
      }
      float hash13(vec3 p) {
        p = fract(p * 0.1031);
        p += dot(p, p.zyx + 31.32);
        return fract((p.x + p.y) * p.z);
      }
      float vnoise(vec3 p) {
        vec3 i = floor(p);
        vec3 f = fract(p);
        vec3 u = f * f * (3.0 - 2.0 * f);
        return mix(
          mix(mix(hash13(i), hash13(i + vec3(1, 0, 0)), u.x), mix(hash13(i + vec3(0, 1, 0)), hash13(i + vec3(1, 1, 0)), u.x), u.y),
          mix(mix(hash13(i + vec3(0, 0, 1)), hash13(i + vec3(1, 0, 1)), u.x), mix(hash13(i + vec3(0, 1, 1)), hash13(i + vec3(1, 1, 1)), u.x), u.y),
          u.z);
      }
      float fbm(vec3 p, int oct) {
        float a = 0.5;
        float s = 0.0;
        for (int i = 0; i < 6; i++) {
          if (i >= oct) break;
          s += a * vnoise(p);
          p = p * 2.03 + 17.1;
          a *= 0.5;
        }
        return s;
      }

      // one layer of craters scattered through 3D cells; returns height in sphere units
      float craterLayer(vec3 p, float scale, float density, inout float fresh) {
        vec3 q = p * scale;
        vec3 i = floor(q);
        vec3 f = fract(q);
        float h = 0.0;
        for (int x = -1; x <= 1; x++)
        for (int y = -1; y <= 1; y++)
        for (int z = -1; z <= 1; z++) {
          vec3 c = i + vec3(x, y, z);
          vec3 r = hash33(c);
          if (r.x > density) continue;
          vec3 center = vec3(x, y, z) + 0.15 + 0.7 * hash33(c + 11.7);
          float rad = 0.12 + 0.4 * r.y * r.y * r.y;
          float d = length(f - center) / rad;
          if (d > 1.7) continue;
          float bowl = (d * d - 1.0) * 0.42 * (1.0 - smoothstep(0.7, 1.02, d));
          float floorFlat = smoothstep(0.0, 0.45, d); // larger craters get flatter floors
          float rim = 0.2 * exp(-pow((d - 1.0) * 2.8, 2.0));
          float ejecta = 0.05 * (1.0 - smoothstep(1.0, 1.7, d));
          h += (bowl * mix(1.0, floorFlat, r.y) + rim + ejecta) * rad / scale;
          fresh += step(0.86, r.z) * (1.0 - smoothstep(0.0, 1.5, d)) * 0.8;
        }
        return h;
      }

      // footprint-aware height: tiny craters fade out when the moon is small (no shimmer)
      float heightAt(vec3 p, float fp, float mare, inout float fresh) {
        float w2 = smoothstep(1.5 * fp, 5.0 * fp, 1.0 / 8.0);
        float w3 = smoothstep(1.5 * fp, 5.0 * fp, 1.0 / 19.0);
        float f1 = 0.0, f2 = 0.0, f3 = 0.0;
        float h = craterLayer(p, 3.0, 0.3, f1);
        h += craterLayer(p + 3.1, 8.0, 0.32, f2) * w2;
        h += craterLayer(p + 7.7, 19.0, 0.4, f3) * w3;
        h *= mix(1.0, 0.5, mare); // maria are smoother
        h += (fbm(p * 5.0, 4) - 0.5) * 0.02;            // rolling terrain
        h += (fbm(p * 30.0, 3) - 0.5) * 0.004 * w3;
        fresh = f1 + f2 * 0.7 * w2 + f3 * 0.4 * w3;
        return h;
      }

      float rays(vec3 n, vec3 R, float seed) {
        float c = dot(n, R);
        float ang = acos(clamp(c, -1.0, 1.0));
        if (ang > 1.1) return 0.0;
        vec3 a = normalize(cross(R, abs(R.y) < 0.9 ? vec3(0, 1, 0) : vec3(1, 0, 0)));
        vec3 b = cross(R, a);
        vec3 t = n - R * c;
        float phi = atan(dot(t, b), dot(t, a));
        float s = vnoise(vec3(cos(phi) * 9.0, sin(phi) * 9.0, seed));
        s = pow(s, 4.0) * 2.0;
        return s * pow(smoothstep(1.1, 0.05, ang), 2.0) * smoothstep(0.02, 0.07, ang);
      }

      void main() {
        vec3 n = normalize(vPos);
        float fp = length(fwidth(vPos));

        // maria: big dark basalt plains, mostly on one hemisphere
        float mare = smoothstep(0.44, 0.56, fbm(n * 1.5 + vec3(4.2, 1.3, 7.7), 5) + 0.06 * fbm(n * 6.0, 3));
        mare *= smoothstep(-0.35, 0.45, dot(n, normalize(vec3(0.25, 0.15, 1.0))));

        // bumped normal from central differences on the tangent plane
        vec3 t1 = normalize(cross(n, abs(n.y) < 0.99 ? vec3(0, 1, 0) : vec3(1, 0, 0)));
        vec3 t2 = cross(n, t1);
        float e = max(0.0012, fp * 0.6);
        float fresh = 0.0, tmp = 0.0;
        float h0 = heightAt(n, fp, mare, fresh);
        float h1 = heightAt(normalize(n + t1 * e), fp, mare, tmp);
        float h2 = heightAt(normalize(n + t2 * e), fp, mare, tmp);
        vec3 grad = (h1 - h0) / e * t1 + (h2 - h0) / e * t2;
        vec3 N = normalize(n - grad * 0.95);

        // albedo (sRGB-ish values, converted to linear below)
        vec3 high = vec3(0.70, 0.69, 0.665);
        vec3 sea = vec3(0.30, 0.305, 0.33);
        vec3 alb = mix(high, sea, mare * 0.92);
        alb *= 0.82 + 0.34 * fbm(n * 6.0 + 2.0, 5);
        alb *= 0.93 + 0.14 * fbm(n * 40.0, 2);
        alb += fresh * 0.05;
        alb += rays(n, normalize(vec3(-0.25, -0.5, 0.83)), 3.0) * 0.07;
        alb += rays(n, normalize(vec3(0.55, 0.3, 0.78)), 9.0) * 0.05;
        alb = clamp(alb, 0.0, 1.0);
        vec3 albLin = pow(alb, vec3(2.2));

        // lunar-ish shading: Lambert blended with Lommel-Seeliger (flat-ish disc), soft terminator
        vec3 L = normalize(uLight);
        vec3 V = normalize(uView - vPos);
        float cosi = max(dot(N, L), 0.0);
        float cose = max(dot(N, V), 0.0);
        float ls = cosi / (cosi + cose + 1e-4);
        float diff = mix(cosi, 2.0 * ls, 0.5);
        float term = smoothstep(-0.06, 0.16, dot(n, L));
        vec3 col = albLin * diff * term * 1.15;
        col += albLin * vec3(0.035, 0.05, 0.07) * (1.0 - term);       // earthshine
        float limb = pow(1.0 - max(dot(n, V), 0.0), 3.0);
        col += vec3(0.55, 0.85, 0.75) * limb * 0.10;                    // faint cool rim, matches the halo
        col += albLin * uGlow * 1.1 + vec3(1.0, 0.9, 0.5) * uGlow * 0.15; // moonshot flash

        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }`,
  });
}

function haloTexture() {
  const s = 256;
  const c = document.createElement('canvas');
  c.width = c.height = s;
  const g = c.getContext('2d')!;
  const grad = g.createRadialGradient(s / 2, s / 2, s * 0.15, s / 2, s / 2, s / 2);
  grad.addColorStop(0, 'rgba(255,250,232,0.42)');
  grad.addColorStop(0.28, 'rgba(240,248,236,0.16)');
  grad.addColorStop(0.6, 'rgba(190,255,228,0.05)');
  grad.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, s, s);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}
