import * as THREE from 'three';
import Matter from 'matter-js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { LEVELS, MAX_LEVEL, MOON_BONUS, PALETTE, S, WORLD, pickDropLevel } from './config';
import { HEAD_STYLES, HEAD_VIEW, HEAD_W, TONGUE, headShapes, headSvg } from './heads';
import { Sky } from './sky';
import { Moon } from './moon';
import { FRAME_STYLES, buildJar, type FrameStyle, type Jar } from './jar';
import { Market } from './market';
import { ChartPanel } from './chart';

const { Engine, Bodies, Body, Composite, Events, Vertices } = Matter;

const W = WORLD.width;
const H = WORLD.height;
/** frame thickness towards the camera; the play plane is z = 0 */
const FRAME_DEPTH = 0.34;
/** the chart panel sits this far behind the play plane */
const BACK_Z = -0.45;
const PHYS_STEP = 1000 / 120;
export const DEFAULT_FRAME: FrameStyle = 'terminal';
const TEX_SIZE = 512;
/** one tongue flick: slide out, flicker the fork, slide back in (seconds) */
const TONGUE_DUR = 0.52;
/** delay between the danger alarm and the jar bursting, and until the result card (ms, game time) */
const BLAST_AT = 650;
const OVER_CARD_AT = 2400;

/** per-level head art + collision layout */
interface HeadTemplate {
  geo: THREE.PlaneGeometry;
  open: THREE.MeshBasicMaterial;
  closed: THREE.MeshBasicMaterial;
  depth: THREE.MeshDepthMaterial;
  /** collision parts in physics units, relative to the image centre */
  parts: (
    | { circle: [number, number, number] }
    | { poly: { x: number; y: number }[]; c: { x: number; y: number } }
  )[];
  /** horizontal extent of all parts, relative to the image centre */
  minX: number;
  maxX: number;
  /** tongue parts, scaled to this head */
  stemGeo: THREE.PlaneGeometry;
  forkGeo: THREE.PlaneGeometry;
  tongueAt: { x: number; y: number };
  stemLen: number;
}

type Move = { kind: 'dance' | 'sad'; t: number } | null;

interface Visual {
  root: THREE.Group; // follows physics (body position + angle)
  inner: THREE.Group; // image centre; pop / squash / wiggle
  mesh: THREE.Mesh;
  move: Move;
  phase: number;
  blinkIn: number;
  blinkT: number;
  tongueIn: number;
  /** time into the current flick (0 = tongue in) */
  tongueT: number;
  tongue: THREE.Group;
  stem: THREE.Group;
  fork: THREE.Group;
  /** 0..1+ : trembling while sitting over the red line */
  nervous: number;
  /** grow-in scale after spawning */
  pop: number;
}

interface Piece extends Visual {
  level: number;
  body: Matter.Body | null;
  bornAt: number;
  settled: boolean;
  overTime: number;
  merging: boolean;
}

export interface ScreenPos {
  x: number;
  y: number;
}

export interface GameEvents {
  score(total: number, gained: number, at: ScreenPos, combo: number): void;
  merged(level: number, combo: number): void;
  next(level: number): void;
  danger(amount: number): void; // 0..1
  /** a head stayed over the line too long: alarm before the jar bursts */
  alarm(): void;
  /** the jar bursts */
  liquidate(at: ScreenPos): void;
  /** time for the result card */
  over(): void;
  /** two Golden SNEKs merged; `first` = the first moon shot of this run (the win) */
  moon(at: ScreenPos, first: boolean): void;
  /** time for the win card */
  won(): void;
  firework(): void;
}

export type GameState = 'ready' | 'playing' | 'paused' | 'won' | 'over';

export class Game {
  state: GameState = 'ready';
  score = 0;
  bestLevelThisRun = 0;

  private renderer: THREE.WebGLRenderer;
  private scene = new THREE.Scene();
  private camera = new THREE.PerspectiveCamera(36, 1, 0.1, 200);
  private camBase = new THREE.Vector3();
  private camLook = new THREE.Vector3();
  private raycaster = new THREE.Raycaster();
  private aimPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
  private clock = new THREE.Clock();
  private insets = { top: 70, bottom: 90 };

  private engine = Engine.create({ positionIterations: 8, velocityIterations: 6 });
  private acc = 0;
  private now = 0; // game time in ms (pauses when paused)
  private pieces = new Map<number, Piece>();
  private pending: [Piece, Piece][] = [];

  private templates: HeadTemplate[] = [];
  private zOrder = 0;

  private dropper: Piece | null = null;
  private currentLevel = 0;
  private nextLevel = 0;
  private aimX = W / 2;
  private lastDropAt = -1e9;
  private keys = { left: false, right: false };

  private combo = 0;
  private comboUntil = 0;
  private shake = 0;
  private dangerLevel = 0;
  private overAt = 0;
  private overPhase: 'alarm' | 'blast' | 'done' = 'done';
  private culprit: Piece | null = null;
  private blasts: { root: THREE.Object3D; vel: THREE.Vector3; spin: THREE.Vector3 }[] = [];
  private jarKick = 0;
  /** real seconds of slow motion left */
  private slowmo = 0;
  private startedAt = 0;
  /** first moon shot done this run */
  private won = false;
  /** between the winning merge and the win card: no drops, no liquidation */
  private celebrating = false;
  private fwQueue: number[] = [];
  private winCardAt = 0;
  /** game time of the winning merge since the run started (ms) */
  winMs = 0;

  private dangerLine!: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial>;
  private guide!: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial>;
  private moon!: Moon;
  private jar!: Jar;
  private market = new Market();
  private chart!: ChartPanel;
  /** current jar frame theme */
  theme: FrameStyle = DEFAULT_FRAME;
  private fillets: Matter.Body[] = [];
  private sky!: Sky;
  private particles!: Particles;
  private pops!: EmotePops;
  private flights: {
    root: THREE.Object3D;
    from: THREE.Vector3;
    t: number;
    dur: number;
    spin: number;
    big: boolean;
  }[] = [];
  private stemMats!: THREE.MeshBasicMaterial[];
  private forkMats!: THREE.MeshBasicMaterial[];

  private constructor(
    private container: HTMLElement,
    private events: GameEvents,
  ) {
    this.renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: 'high-performance',
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.05;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.domElement.className = 'game-canvas';
    container.appendChild(this.renderer.domElement);
  }

  static async load(
    container: HTMLElement,
    events: GameEvents,
    onProgress: (p: number) => void,
    frame: FrameStyle = DEFAULT_FRAME,
  ): Promise<Game> {
    const g = new Game(container, events);
    g.theme = FRAME_STYLES.includes(frame) ? frame : DEFAULT_FRAME;
    await g.loadAssets(onProgress);
    g.buildScene();
    g.setupPhysics();
    g.resize();
    window.addEventListener('resize', () => g.resize());
    g.renderer.setAnimationLoop(() => g.frame());
    return g;
  }

  // ---------------------------------------------------------------- assets
  private async loadAssets(onProgress: (p: number) => void) {
    let done = 0;
    const total = LEVELS.length;
    const mat = (map: THREE.Texture) =>
      new THREE.MeshBasicMaterial({ map, transparent: true, depthWrite: false, toneMapped: false });
    const [stemInk, stemFill, forkInk, forkFill] = await Promise.all([
      svgTexture(TONGUE.stem.ink, TONGUE.stem.w, TONGUE.stem.h),
      svgTexture(TONGUE.stem.fill, TONGUE.stem.w, TONGUE.stem.h),
      svgTexture(TONGUE.fork.ink, TONGUE.fork.w, TONGUE.fork.h),
      svgTexture(TONGUE.fork.fill, TONGUE.fork.w, TONGUE.fork.h),
    ]);
    this.stemMats = [mat(stemInk), mat(stemFill)];
    this.forkMats = [mat(forkInk), mat(forkFill)];
    this.templates = await Promise.all(
      LEVELS.map(async (def, i) => {
        const style = HEAD_STYLES[i];
        const [openTex, closedTex] = await Promise.all([
          svgTexture(headSvg(style)),
          svgTexture(headSvg(style, { closed: true })),
        ]);
        onProgress(++done / total);
        const k = def.size / HEAD_W; // svg unit -> physics unit
        const geo = new THREE.PlaneGeometry(TEX_SIZE * k * S, TEX_SIZE * k * S);
        // tongue: logo units -> world units for this head size
        const u = (TEX_SIZE * k * S) / HEAD_VIEW.s;
        const cx = HEAD_VIEW.x + HEAD_VIEW.s / 2;
        const cy = HEAD_VIEW.y + HEAD_VIEW.s / 2;
        const stemGeo = new THREE.PlaneGeometry(TONGUE.stem.w * u, TONGUE.stem.h * u).translate(
          (TONGUE.stem.w / 2 - TONGUE.pad) * u,
          0,
          0,
        );
        const forkGeo = new THREE.PlaneGeometry(TONGUE.fork.w * u, TONGUE.fork.h * u).translate(
          (TONGUE.fork.w / 2 - TONGUE.pad) * u,
          0,
          0,
        );
        const tongueAt = { x: (TONGUE.anchor[0] - cx) * u, y: -(TONGUE.anchor[1] - cy) * u };
        const depth = new THREE.MeshDepthMaterial({
          depthPacking: THREE.RGBADepthPacking,
          map: openTex,
          alphaTest: 0.5,
        });

        let minX = Infinity;
        let maxX = -Infinity;
        const parts: HeadTemplate['parts'] = headShapes(style).map((sh) => {
          if ('circle' in sh) {
            const [x, y, r] = sh.circle;
            const c: [number, number, number] = [(x - 256) * k, (y - 256) * k, r * k];
            minX = Math.min(minX, c[0] - c[2]);
            maxX = Math.max(maxX, c[0] + c[2]);
            return { circle: c };
          }
          const poly = sh.poly.map(([x, y]) => ({ x: (x - 256) * k, y: (y - 256) * k }));
          for (const p of poly) {
            minX = Math.min(minX, p.x);
            maxX = Math.max(maxX, p.x);
          }
          return { poly, c: Vertices.centre(poly) };
        });
        return {
          geo,
          open: mat(openTex),
          closed: mat(closedTex),
          depth,
          parts,
          minX,
          maxX,
          stemGeo,
          forkGeo,
          tongueAt,
          stemLen: (TONGUE.len - 8) * u,
        };
      }),
    );
  }

  // ---------------------------------------------------------------- scene
  private buildScene() {
    const scene = this.scene;
    scene.background = new THREE.Color(PALETTE.bg);
    scene.fog = new THREE.Fog(PALETTE.bg, 30, 60);

    const pmrem = new THREE.PMREMGenerator(this.renderer);
    scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
    scene.environmentIntensity = 0.45;

    scene.add(new THREE.HemisphereLight(0xe8fff4, 0x1c2a22, 1.5));
    const sun = new THREE.DirectionalLight(0xffffff, 2.4);
    sun.position.set(3.5, 13, 9);
    sun.target.position.set(0, 3.5, 0);
    sun.castShadow = true;
    sun.shadow.mapSize.set(1024, 1024);
    const sc = sun.shadow.camera;
    sc.left = -5;
    sc.right = 5;
    sc.top = 6;
    sc.bottom = -6;
    sc.near = 1;
    sc.far = 30;
    sun.shadow.intensity = 0.65;
    sun.shadow.bias = -0.0008;
    sun.shadow.normalBias = 0.02;
    scene.add(sun, sun.target);

    // --- jar
    this.buildJar();

    // danger line
    this.dangerLine = new THREE.Mesh(
      new THREE.PlaneGeometry(W * S, 0.04),
      new THREE.MeshBasicMaterial({
        color: PALETTE.red,
        transparent: true,
        opacity: 0.35,
        toneMapped: false,
        depthWrite: false,
      }),
    );
    this.dangerLine.position.set(0, (H - WORLD.dangerY) * S, 0.004);
    this.dangerLine.renderOrder = 1e7; // stays visible over the heads
    scene.add(this.dangerLine);

    // aim guide
    this.guide = new THREE.Mesh(
      new THREE.PlaneGeometry(0.035, 1),
      new THREE.MeshBasicMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0.22,
        depthWrite: false,
      }),
    );
    this.guide.position.z = 0.01;
    scene.add(this.guide);

    // the moon (positions itself in resize())
    this.moon = new Moon();
    scene.add(this.moon.root);

    // twinkling stars, shooting stars and the occasional UFO (piloted by the Whale SNEK)
    const pilot = this.templates[LEVELS.findIndex((l) => l.id === 'whale')].open.map!;
    this.sky = new Sky(scene, () => this.skyBand(), pilot);

    this.particles = new Particles(scene);
    this.pops = new EmotePops(scene);
  }

  /** The chart panel behind the jar, then the frame itself (swappable at runtime via setFrame). */
  private buildJar() {
    const scene = this.scene;
    const w = W * S;
    const h = H * S;
    const t = WORLD.wall * S;
    // live SNEK candles on the back panel
    this.chart = new ChartPanel(this.market, { w, h, t, backZ: BACK_Z });
    scene.add(this.chart.mesh);
    this.market.start();
    this.setFrame(this.theme, true);

    // dark floor shadow band so the bottom reads as "ground"
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(w, 0.5),
      new THREE.MeshBasicMaterial({ map: makeFadeTexture(), transparent: true, depthWrite: false }),
    );
    ground.position.set(0, 0.25, BACK_Z + 0.01);
    scene.add(ground);
  }

  /** Swap the jar frame theme. Heads stay where they are; corners, camera and moon adapt. */
  setFrame(style: FrameStyle, force = false) {
    if (!FRAME_STYLES.includes(style) || (style === this.theme && this.jar && !force)) return;
    this.theme = style;
    if (this.jar) {
      this.scene.remove(this.jar.group);
      disposeTree(this.jar.group);
    }
    this.jar = buildJar(style, {
      w: W * S,
      h: H * S,
      t: WORLD.wall * S,
      depth: FRAME_DEPTH,
      dangerY: (H - WORLD.dangerY) * S,
      backZ: BACK_Z,
    });
    this.scene.add(this.jar.group);
    this.chart?.setCompact(style === 'terminal');
    this.setFillets(this.jar.innerRadius / S);
    this.resize();
  }

  /** rounded inner bottom corners: a fan of thin static triangles that follows the drawn arc exactly */
  private setFillets(R: number) {
    if (this.fillets.length) Composite.remove(this.engine.world, this.fillets);
    this.fillets = [];
    if (R <= 0) return;
    const opts = { isStatic: true, friction: 0.5, restitution: 0.05 };
    const seg = 10;
    for (const side of [-1, 1]) {
      const cx = side < 0 ? R : W - R;
      const cy = H - R;
      const corner = { x: side < 0 ? 0 : W, y: H };
      for (let i = 0; i < seg; i++) {
        const pt = (a: number) => ({ x: cx + side * Math.cos(a) * R, y: cy + Math.sin(a) * R });
        const tri = [corner, pt((i / seg) * (Math.PI / 2)), pt(((i + 1) / seg) * (Math.PI / 2))];
        const c = Vertices.centre(tri);
        this.fillets.push(Bodies.fromVertices(c.x, c.y, [tri], opts));
      }
    }
    Composite.add(this.engine.world, this.fillets);
  }

  // ---------------------------------------------------------------- physics
  private setupPhysics() {
    const t = WORLD.wall;
    const opts = { isStatic: true, friction: 0.5, restitution: 0.05 };
    Composite.add(this.engine.world, [
      Bodies.rectangle(W / 2, H + t / 2, W + t * 2, t, opts),
      Bodies.rectangle(-t / 2, H / 2 - H / 2, t, H * 2, opts),
      Bodies.rectangle(W + t / 2, H / 2 - H / 2, t, H * 2, opts),
    ]);

    const onPairs = (e: Matter.IEventCollision<Matter.Engine>) => {
      for (const pair of e.pairs) {
        const a = this.pieces.get(pair.bodyA.parent.id);
        const b = this.pieces.get(pair.bodyB.parent.id);
        if (a && !a.settled) this.settle(a);
        if (b && !b.settled) this.settle(b);
        if (!a || !b || a.merging || b.merging || a.level !== b.level) continue;
        if (this.state !== 'playing') continue;
        a.merging = b.merging = true;
        this.pending.push([a, b]);
      }
    };
    Events.on(this.engine, 'collisionStart', onPairs);
    Events.on(this.engine, 'collisionActive', onPairs);
  }

  private settle(p: Piece) {
    p.settled = true;
    if (this.now - p.bornAt < 3000 && p.body) {
      const speed = p.body.speed;
      if (speed > 2) this.sfxThud?.(speed);
    }
  }

  /** set from main for sound hooks without coupling */
  sfxThud?: (speed: number) => void;
  sfxDrop?: () => void;

  // ---------------------------------------------------------------- pieces
  private makeVisual(level: number): Visual {
    const tpl = this.templates[level];
    const root = new THREE.Group();
    const inner = new THREE.Group();
    const mesh = new THREE.Mesh(tpl.geo, tpl.open);
    mesh.castShadow = true;
    mesh.customDepthMaterial = tpl.depth;
    // all heads share the z = 0 plane; newer ones draw on top instead of z-fighting
    this.zOrder += 3;
    mesh.renderOrder = this.zOrder;
    // tongue: outlines first, then fills, so stem and fork join without a seam
    const layer = (geo: THREE.PlaneGeometry, mats: THREE.MeshBasicMaterial[]) => {
      const g = new THREE.Group();
      mats.forEach((m, i) => {
        const part = new THREE.Mesh(geo, m);
        part.renderOrder = this.zOrder + 1 + i;
        g.add(part);
      });
      return g;
    };
    const stem = layer(tpl.stemGeo, this.stemMats);
    const fork = layer(tpl.forkGeo, this.forkMats);
    const tongue = new THREE.Group();
    tongue.position.set(tpl.tongueAt.x, tpl.tongueAt.y, 0);
    tongue.rotation.z = TONGUE.angle;
    tongue.add(stem, fork);
    tongue.visible = false;
    inner.add(mesh, tongue);
    root.add(inner);
    this.scene.add(root);
    return {
      root,
      inner,
      mesh,
      move: null,
      phase: Math.random() * 10,
      blinkIn: 1 + Math.random() * 4,
      blinkT: 0,
      tongueIn: 1.5 + Math.random() * 6,
      tongueT: 0,
      tongue,
      stem,
      fork,
      nervous: 0,
      pop: 1,
    };
  }

  /** Compound body that follows the drawn head: face ellipse + eye bulges + accessory. (x, y) = image centre. */
  private spawnPiece(level: number, x: number, y: number, visual?: Visual): Piece {
    const tpl = this.templates[level];
    const opts = {
      restitution: 0.1,
      friction: 0.4,
      frictionStatic: 0.7,
      density: 0.0012,
      frictionAir: 0.006,
    };
    const parts = tpl.parts.map((pt) =>
      'circle' in pt
        ? Bodies.circle(x + pt.circle[0], y + pt.circle[1], pt.circle[2], opts)
        : Bodies.fromVertices(
            x + pt.c.x,
            y + pt.c.y,
            [pt.poly.map((v) => ({ x: v.x + x, y: v.y + y }))],
            opts,
          ),
    );
    const body = Body.create({ ...opts, parts });
    // heavier rotational inertia: heads still roll, but faces mostly stay readable
    Body.setInertia(body, body.inertia * 2.2);
    Composite.add(this.engine.world, body);
    const v = visual ?? this.makeVisual(level);
    // the image centre relative to the centre of mass (body space, angle 0)
    v.inner.position.set((x - body.position.x) * S, -(y - body.position.y) * S, 0);
    const piece: Piece = {
      ...v,
      level,
      body,
      bornAt: this.now,
      settled: false,
      overTime: 0,
      merging: false,
    };
    this.pieces.set(body.id, piece);
    this.syncPiece(piece);
    return piece;
  }

  private removePiece(p: Piece, keepVisual = false) {
    if (p.body) {
      Composite.remove(this.engine.world, p.body);
      this.pieces.delete(p.body.id);
      p.body = null;
    }
    if (!keepVisual) this.disposeVisual(p);
  }

  private disposeVisual(p: Visual) {
    this.scene.remove(p.root);
  }

  /** breathing, blinking, merge dance and the game-over wobble */
  private animate(v: Visual, level: number, dt: number) {
    const tpl = this.templates[level];
    v.phase += dt;
    const breath = Math.sin(v.phase * 2.3) * 0.018;
    let sx = 1 - breath * 0.6;
    let sy = 1 + breath;
    let rz = 0;
    let closed = false;
    if (v.move) {
      const m = v.move;
      m.t += dt;
      if (m.kind === 'dance') {
        const d = 0.8;
        const k = Math.max(0, 1 - m.t / d);
        const squash = Math.sin(m.t * 24) * 0.15 * k;
        sx += squash;
        sy -= squash;
        rz = Math.sin(m.t * 15) * 0.15 * k;
        closed = m.t < 0.55; // happy squint
        if (m.t >= d) v.move = null;
      } else {
        rz = Math.sin(m.t * 17 + v.phase) * 0.07;
      }
    }
    v.blinkIn -= dt;
    if (v.blinkIn <= 0) {
      v.blinkT = 0.13;
      v.blinkIn = 2.2 + Math.random() * 4.5;
    }
    if (v.blinkT > 0) {
      v.blinkT -= dt;
      closed = true;
    }
    // snake tell: the forked tongue slides out, the tips flicker up and down, then it slides back in
    v.tongueIn -= dt;
    if (v.tongueIn <= 0 && v.tongueT <= 0 && !closed) {
      v.tongueT = 1e-6;
      v.tongueIn = TONGUE_DUR + (Math.random() < 0.3 ? 0.1 : 3 + Math.random() * 6); // sometimes a double flick
    }
    let ext = 0;
    const tt = v.tongueT;
    if (tt > 0) {
      v.tongueT += dt;
      if (v.tongueT >= TONGUE_DUR) v.tongueT = 0;
      const OUT = 0.08;
      const IN = 0.11;
      if (tt < OUT) ext = 1 - (1 - tt / OUT) ** 3;
      else if (tt > TONGUE_DUR - IN) {
        const k = Math.max(0, (TONGUE_DUR - tt) / IN);
        ext = k * k * (3 - 2 * k);
      } else ext = 1;
    }
    v.tongue.visible = ext > 0.01;
    if (v.tongue.visible) {
      const wig = Math.min(1, tt / 0.1);
      v.stem.scale.set(ext, 0.75 + 0.25 * ext, 1);
      v.fork.position.x = tpl.stemLen * ext;
      const f = 0.3 + 0.7 * ext;
      v.fork.scale.set(f, f, 1);
      v.fork.rotation.z = Math.sin(tt * 78) * 0.42 * wig;
      v.tongue.rotation.z = TONGUE.angle + Math.sin(tt * 39 + 0.6) * 0.08 * wig;
    }
    // over the red line: nervous trembling, harder the closer to liquidation
    if (v.nervous > 0) {
      const n = Math.min(1.6, v.nervous);
      rz += Math.sin(v.phase * 61) * 0.05 * n;
      sx += Math.sin(v.phase * 47) * 0.025 * n;
    }
    v.mesh.material = closed ? tpl.closed : tpl.open;
    v.inner.scale.set(sx * v.pop, sy * v.pop, 1);
    v.inner.rotation.z = rz;
  }

  private syncPiece(p: Piece) {
    if (!p.body) return;
    p.root.position.set((p.body.position.x - W / 2) * S, (H - p.body.position.y) * S, 0);
    p.root.rotation.z = -p.body.angle;
  }

  // ---------------------------------------------------------------- control
  start() {
    for (const p of [...this.pieces.values()]) this.removePiece(p);
    for (const f of this.flights) this.scene.remove(f.root);
    this.flights = [];
    for (const b of this.blasts) this.scene.remove(b.root);
    this.blasts = [];
    this.jarKick = 0;
    this.jar.group.scale.set(1, 1, 1);
    this.overPhase = 'done';
    this.culprit = null;
    this.won = false;
    this.celebrating = false;
    this.fwQueue = [];
    this.winCardAt = 0;
    this.winMs = 0;
    this.slowmo = 0;
    this.startedAt = this.now;
    this.pending = [];
    if (this.dropper) this.disposeVisual(this.dropper);
    this.dropper = null;
    this.score = 0;
    this.bestLevelThisRun = 0;
    this.combo = 0;
    this.dangerLevel = 0;
    this.lastDropAt = -1e9;
    this.aimX = W / 2;
    this.currentLevel = pickDropLevel();
    this.nextLevel = pickDropLevel();
    this.state = 'playing';
    this.makeDropper();
    this.events.next(this.nextLevel);
    this.events.score(0, 0, { x: 0, y: 0 }, 0);
  }

  pause() {
    if (this.state === 'playing') this.state = 'paused';
  }

  /** after the win card: keep playing for score */
  continueRun() {
    if (this.state !== 'won') return;
    this.state = 'playing';
    this.celebrating = false;
    this.clock.getDelta();
  }

  get elapsedMs() {
    return this.now - this.startedAt;
  }

  /** this run already reached the moon (so its end is a take-profit, not a liquidation) */
  get hasWon() {
    return this.won;
  }

  resume() {
    if (this.state === 'paused') {
      this.state = 'playing';
      this.clock.getDelta();
    }
  }

  setInsets(top: number, bottom: number) {
    this.insets = { top, bottom };
    this.resize();
  }

  setKey(dir: 'left' | 'right', down: boolean) {
    this.keys[dir] = down;
  }

  /** client coords -> aim position */
  aimAtClient(clientX: number, clientY: number) {
    const rect = this.renderer.domElement.getBoundingClientRect();
    const ndc = new THREE.Vector2(
      ((clientX - rect.left) / rect.width) * 2 - 1,
      -((clientY - rect.top) / rect.height) * 2 + 1,
    );
    this.raycaster.setFromCamera(ndc, this.camera);
    const hit = new THREE.Vector3();
    if (this.raycaster.ray.intersectPlane(this.aimPlane, hit)) this.aimX = hit.x / S + W / 2;
  }

  drop() {
    if (this.state !== 'playing' || !this.dropper || this.celebrating) return;
    if (this.now - this.lastDropAt < WORLD.dropCooldownMs) return;
    const x = this.clampAim(this.currentLevel);
    const visual = this.dropper;
    this.dropper = null;
    const p = this.spawnPiece(this.currentLevel, x, WORLD.spawnY, visual);
    Body.setVelocity(p.body!, { x: 0, y: 2 });
    Body.setAngularVelocity(p.body!, (Math.random() - 0.5) * 0.02);
    this.lastDropAt = this.now;
    this.sfxDrop?.();
    this.currentLevel = this.nextLevel;
    this.nextLevel = pickDropLevel();
    this.events.next(this.nextLevel);
  }

  private makeDropper() {
    const v = this.makeVisual(this.currentLevel);
    this.dropper = {
      level: this.currentLevel,
      body: null,
      ...v,
      bornAt: this.now,
      settled: false,
      overTime: 0,
      merging: false,
    };
    this.dropper.pop = 0.01;
  }

  private clampAim(level: number) {
    const tpl = this.templates[level];
    this.aimX = Math.min(W - tpl.maxX - 2, Math.max(-tpl.minX + 2, this.aimX));
    return this.aimX;
  }

  // ---------------------------------------------------------------- merges
  private processMerges() {
    if (!this.pending.length) return;
    const list = this.pending;
    this.pending = [];
    for (const [a, b] of list) {
      if (!a.body || !b.body) continue;
      const pa = a.body.position;
      const pb = b.body.position;
      const mid = { x: (pa.x + pb.x) / 2, y: (pa.y + pb.y) / 2 };
      const vel = {
        x: (a.body.velocity.x + b.body.velocity.x) / 4,
        y: (a.body.velocity.y + b.body.velocity.y) / 4,
      };
      const level = a.level;

      if (this.now < this.comboUntil) this.combo++;
      else this.combo = 1;
      this.comboUntil = this.now + 1100;
      const mult = 1 + (this.combo - 1) * 0.25;
      const world = new THREE.Vector3((mid.x - W / 2) * S, (H - mid.y) * S, 0.3);

      if (level === MAX_LEVEL) {
        // TO THE MOON (the first one of a run is the win)
        const first = !this.won;
        if (first) {
          this.won = true;
          this.celebrating = true;
          this.winMs = this.now - this.startedAt;
          this.slowmo = 0.75;
          // the danger clock stops while celebrating
          for (const p of this.pieces.values()) p.overTime = p.nervous = 0;
          this.dangerLevel = 0;
        }
        this.removePiece(a, true);
        this.removePiece(b, true);
        for (const p of [a, b]) {
          p.tongue.visible = false;
          // fly in front of the jar so the spinning head never dips behind the back panel
          this.flights.push({
            root: p.root,
            from: p.root.position.clone().setZ(1.2),
            t: 0,
            dur: 1.6,
            spin: (Math.random() - 0.5) * 8,
            big: first,
          });
        }
        const gained = Math.round(MOON_BONUS * mult);
        this.score += gained;
        this.particles.burst(world, PALETTE.gold, first ? 110 : 60, first ? 9 : 7);
        if (first) this.particles.burst(world, '#ffffff', 30, 5);
        else this.pops.pop('stars', world, 1.4);
        this.shake = first ? 0.5 : 0.35;
        this.events.score(this.score, gained, this.toScreen(world), this.combo);
        this.events.moon(this.toScreen(world), first);
        if (first) this.events.danger(0);
        continue;
      }

      this.removePiece(a);
      this.removePiece(b);
      const nl = level + 1;
      // big heads: keep the merged one inside the walls so it doesn't spawn half in a wall
      const nt = this.templates[nl];
      const nx = Math.min(W - nt.maxX - 1, Math.max(-nt.minX + 1, mid.x));
      const np = this.spawnPiece(nl, nx, mid.y);
      np.settled = true;
      Body.setVelocity(np.body!, vel);
      np.pop = 0.55;
      np.move = { kind: 'dance', t: 0 };

      const def = LEVELS[nl];
      const gained = Math.round(def.points * mult);
      this.score += gained;
      this.bestLevelThisRun = Math.max(this.bestLevelThisRun, nl);
      this.particles.burst(world, def.color, 10 + nl * 3, 2.5 + nl * 0.35);
      const emote = nl >= 9 ? 'cash' : nl >= 6 ? 'stars' : nl >= 3 ? 'star' : 'heart';
      this.pops.pop(
        emote,
        world.clone().add(new THREE.Vector3(0, (def.size * S) / 2 + 0.2, 0)),
        0.45 + nl * 0.05,
      );
      if (nl >= 7) this.shake = Math.max(this.shake, 0.06 + (nl - 7) * 0.04);
      this.events.score(this.score, gained, this.toScreen(world), this.combo);
      this.events.merged(nl, this.combo);
    }
  }

  // ---------------------------------------------------------------- loop
  private frame() {
    let dt = Math.min(this.clock.getDelta(), 0.05);
    if (this.slowmo > 0) {
      this.slowmo -= dt;
      dt *= 0.3;
    }
    const running = this.state === 'playing' || this.state === 'over' || this.state === 'won';

    if (running) {
      this.now += dt * 1000;
      if (this.state === 'playing') {
        this.acc += dt * 1000;
        let steps = 0;
        while (this.acc >= PHYS_STEP && steps < 8) {
          Engine.update(this.engine, PHYS_STEP);
          this.processMerges();
          this.acc -= PHYS_STEP;
          steps++;
        }
        if (steps === 8) this.acc = 0;
        this.updateAim(dt);
        if (!this.celebrating) this.checkDanger(dt);
      }
      for (const p of this.pieces.values()) {
        this.syncPiece(p);
        p.pop = Math.min(1, p.pop + dt * 3.5);
        this.animate(p, p.level, dt);
      }
      this.updateFlights(dt);
      this.updateCelebration();
      if (this.state === 'over') this.updateLiquidation(dt);
      this.particles.update(dt);
      this.pops.update(dt);
    }

    // the jar jolts when it bursts
    if (this.jarKick > 0) {
      this.jarKick = Math.max(0, this.jarKick - dt * 1.6);
      const k = this.jarKick;
      const w = Math.sin((1 - k) * Math.PI * 4) * k;
      this.jar.group.scale.set(1 + w * 0.035, 1 - w * 0.025, 1);
    }

    // danger line pulse
    const m = this.dangerLine.material;
    const pulse =
      this.dangerLevel > 0
        ? 0.45 + 0.5 * Math.abs(Math.sin(this.now / (130 - this.dangerLevel * 70)))
        : 0.3;
    m.opacity = this.state === 'over' ? 0.95 : pulse;

    this.moon.update(dt, this.camera);
    this.chart.update(dt);
    this.jar.update(dt, { view: this.chart, project: (x, y, z) => this.projectFromBack(x, y, z) });

    // camera shake
    this.camera.position.copy(this.camBase);
    if (this.shake > 0) {
      this.camera.position.x += (Math.random() - 0.5) * this.shake;
      this.camera.position.y += (Math.random() - 0.5) * this.shake;
      this.shake = Math.max(0, this.shake - dt * 1.2);
    }
    this.camera.lookAt(this.camLook);

    this.sky.update(dt, this.camera, this.renderer.getPixelRatio());
    this.renderer.render(this.scene, this.camera);
  }

  /** where a point on the back panel appears on the plane z, seen from the camera */
  private projectFromBack(x: number, y: number, z: number) {
    const c = this.camBase;
    const k = (z - c.z) / (BACK_Z - c.z);
    return { x: c.x + (x - c.x) * k, y: c.y + (y - c.y) * k };
  }

  /** NDC band between the top of the jar and the bottom of the HUD, where the sky shows */
  private skyBand(): [number, number] {
    const jarTop = new THREE.Vector3(0, (this.jar?.top ?? H * S + 0.3) + 0.15, 0).project(
      this.camera,
    ).y;
    const h = this.renderer.domElement.clientHeight || window.innerHeight;
    const hud = 1 - (2 * (this.insets.top + 12)) / h;
    return [jarTop, hud];
  }

  private updateAim(dt: number) {
    if (this.keys.left) this.aimX -= 520 * dt;
    if (this.keys.right) this.aimX += 520 * dt;
    if (!this.dropper && this.now - this.lastDropAt >= WORLD.dropCooldownMs) this.makeDropper();
    const level = this.dropper ? this.dropper.level : this.currentLevel;
    const x = this.clampAim(level);
    const tx = (x - W / 2) * S;
    if (this.dropper) {
      const d = this.dropper;
      d.root.position.set(tx, (H - WORLD.spawnY) * S + Math.sin(this.now / 260) * 0.04, 0);
      d.root.rotation.z = Math.sin(this.now / 400) * 0.06;
      d.pop = Math.min(1, d.pop + dt * 5);
      this.animate(d, d.level, dt);
    }
    const top = (H - WORLD.spawnY) * S;
    this.guide.visible = !!this.dropper;
    this.guide.scale.y = top;
    this.guide.position.set(tx, top / 2, 0.01);
  }

  private checkDanger(dt: number) {
    let worst = 0;
    for (const p of this.pieces.values()) {
      if (!p.body) continue;
      if (!p.settled && this.now - p.bornAt > 1200) p.settled = true;
      if (!p.settled) continue;
      if (p.body.bounds.min.y < WORLD.dangerY) {
        p.overTime += dt;
        worst = Math.max(worst, p.overTime / WORLD.dangerSeconds);
        if (p.overTime >= WORLD.dangerSeconds) {
          this.gameOver(p);
          return;
        }
      } else {
        p.overTime = Math.max(0, p.overTime - dt * 2);
      }
      p.nervous = p.overTime / WORLD.dangerSeconds;
    }
    if (Math.abs(worst - this.dangerLevel) > 0.01 || (worst === 0 && this.dangerLevel !== 0)) {
      this.dangerLevel = worst;
      this.events.danger(worst);
    }
  }

  /** Liquidation: alarm (everyone trembles) -> the jar bursts and the heads blast out -> result card */
  private gameOver(culprit?: Piece) {
    this.state = 'over';
    this.overAt = this.now;
    this.overPhase = 'alarm';
    this.celebrating = false;
    const all = [...this.pieces.values()];
    this.culprit =
      culprit ??
      all.sort((a, b) => (a.body?.bounds.min.y ?? 1e9) - (b.body?.bounds.min.y ?? 1e9))[0] ??
      null;
    this.dangerLevel = 1;
    this.events.danger(1);
    this.guide.visible = false;
    if (this.dropper) {
      this.disposeVisual(this.dropper);
      this.dropper = null;
    }
    for (const p of all) {
      p.move = { kind: 'sad', t: 0 };
      p.nervous = Math.max(p.nervous, 0.6);
    }
    if (this.culprit) this.culprit.nervous = 2.2;
    this.shake = 0.2;
    this.events.alarm();
  }

  private updateLiquidation(dt: number) {
    const t = this.now - this.overAt;
    if (this.overPhase === 'alarm') {
      // the culprit swells like it's about to pop
      const c = this.culprit;
      if (c)
        c.inner.scale.multiplyScalar(1 + (t / BLAST_AT) * 0.18 + Math.abs(Math.sin(t / 45)) * 0.05);
      if (t >= BLAST_AT) this.blast();
      return;
    }
    for (const b of this.blasts) {
      b.vel.y -= 15 * dt;
      b.root.position.addScaledVector(b.vel, dt);
      b.root.rotation.x += b.spin.x * dt;
      b.root.rotation.y += b.spin.y * dt;
      b.root.rotation.z += b.spin.z * dt;
    }
    if (this.overPhase === 'blast' && t >= OVER_CARD_AT) {
      this.overPhase = 'done';
      this.events.over();
    }
  }

  /** the jar bursts: every head is flung out (towards the camera, spinning), sparks everywhere */
  private blast() {
    this.overPhase = 'blast';
    const center = new THREE.Vector3(0, H * S * 0.3, 0);
    const origin =
      this.culprit?.root.position.clone() ?? new THREE.Vector3(0, (H - WORLD.dangerY) * S, 0);
    origin.z = 0.4;
    for (const p of [...this.pieces.values()]) {
      const pos = p.root.position.clone();
      this.removePiece(p, true);
      p.tongue.visible = false;
      p.root.position.z = 0.7; // in front of the back panel while tumbling
      const dir = pos.clone().sub(center);
      dir.z = 0;
      if (dir.lengthSq() < 1e-4) dir.set(Math.random() - 0.5, 1, 0);
      dir.normalize();
      const sp = 4 + Math.random() * 4.5;
      const vel = new THREE.Vector3(
        dir.x * sp,
        dir.y * sp * 0.5 + 4 + Math.random() * 5,
        1 + Math.random() * 3.5,
      );
      const spin = new THREE.Vector3(
        (Math.random() - 0.5) * 5,
        (Math.random() - 0.5) * 5,
        (Math.random() - 0.5) * 12,
      );
      this.blasts.push({ root: p.root, vel, spin });
      this.particles.burst(pos.setZ(0.3), LEVELS[p.level].color, 5, 4);
    }
    if (this.won) {
      // take-profit: a shower of gold and green instead of a red blast
      this.particles.burst(origin, PALETTE.gold, 90, 9);
      this.particles.burst(origin, PALETTE.green, 40, 6);
      this.particles.burst(center.setZ(0.3), '#ffffff', 20, 7);
      this.shake = 0.45;
    } else {
      this.particles.burst(origin, PALETTE.red, 80, 9);
      this.particles.burst(origin, '#ff9100', 40, 6);
      this.particles.burst(center.setZ(0.3), '#ffffff', 20, 7);
      this.shake = 0.9;
    }
    this.jarKick = 1;
    this.events.liquidate(this.toScreen(origin));
  }

  /** fireworks after the first moon landing, then the win card */
  private updateCelebration() {
    while (this.fwQueue.length && this.now >= this.fwQueue[0]) {
      this.fwQueue.shift();
      this.firework();
    }
    if (this.winCardAt && this.now >= this.winCardAt && this.state === 'playing') {
      this.winCardAt = 0;
      this.state = 'won';
      this.events.won();
    }
  }

  private firework() {
    const colors = [
      PALETTE.gold,
      PALETTE.green,
      '#ff84bf',
      '#8bcfff',
      '#ffffff',
      '#ff9f48',
      '#a07aff',
    ];
    const c = colors[Math.floor(Math.random() * colors.length)];
    const pos = new THREE.Vector3(
      (Math.random() - 0.5) * W * S * 0.95,
      H * S * (0.5 + Math.random() * 0.55),
      0.6,
    );
    const c2 = colors[Math.floor(Math.random() * colors.length)];
    this.particles.burst(pos, c, 50, 6);
    this.particles.burst(pos, c2, 22, 3.5);
    this.particles.burst(pos, '#ffffff', 10, 1.8);
    this.events.firework();
  }

  private updateFlights(dt: number) {
    const target = this.moon.position;
    for (const f of this.flights) {
      f.t += dt / f.dur;
      const k = Math.min(1, f.t);
      const e = k * k * (3 - 2 * k);
      f.root.position.lerpVectors(f.from, target, e);
      f.root.position.y += Math.sin(k * Math.PI) * 2.5;
      // stay in front of the jar (the back panel would slice the head) and only recede towards the
      // moon on the last stretch, when the head is small and already clear of the jar
      const ze = Math.max(0, (e - 0.55) / 0.45);
      let z = f.from.z + (target.z - f.from.z) * ze * ze;
      const p = f.root.position;
      if (Math.abs(p.x) < (W * S) / 2 + 2.2 && p.y < H * S + 2.2) z = Math.max(z, 0.6);
      p.z = z;
      f.root.rotation.z += f.spin * dt;
      f.root.scale.setScalar(1 - e * 0.85);
      if (Math.random() < 0.6) this.particles.burst(f.root.position, PALETTE.gold, 1, 0.6);
      if (k >= 1) {
        this.scene.remove(f.root);
        this.moon.flash();
        this.particles.burst(target.clone(), PALETTE.gold, 40, 5);
        if (f.big && !this.winCardAt && this.state === 'playing' && this.celebrating) {
          // landed: a volley of fireworks over the jar, then the win card
          const at = [0, 220, 420, 650, 820, 1050, 1300, 1500, 1800, 2100, 2500, 2900, 3400, 3900];
          this.fwQueue = at.map((d) => this.now + d + Math.random() * 120);
          this.winCardAt = this.now + 1600;
        }
      }
    }
    this.flights = this.flights.filter((f) => f.t < 1);
  }

  // ---------------------------------------------------------------- view
  private toScreen(v: THREE.Vector3): ScreenPos {
    const p = v.clone().project(this.camera);
    const r = this.renderer.domElement.getBoundingClientRect();
    return { x: r.left + ((p.x + 1) / 2) * r.width, y: r.top + ((1 - p.y) / 2) * r.height };
  }

  private resize() {
    const w = this.container.clientWidth || window.innerWidth;
    const h = this.container.clientHeight || window.innerHeight;
    this.renderer.setSize(w, h);
    this.camera.aspect = w / h;

    const contentW = (W + WORLD.wall * 2) * S + 0.5;
    // frame-aware framing: some frames (e.g. the terminal title bar) rise higher than others
    const contentTop = (this.jar?.top ?? H * S + 0.3) + 0.2;
    const contentBottom = -WORLD.wall * S - 0.4;
    const contentH = contentTop - contentBottom;
    const usable = Math.max(0.4, (h - this.insets.top - this.insets.bottom) / h);
    const tan = Math.tan(THREE.MathUtils.degToRad(this.camera.fov / 2));
    const needH = contentH / usable;
    const dist = Math.max(needH / 2 / tan, contentW / 2 / (tan * this.camera.aspect)) + FRAME_DEPTH;
    const visibleH = 2 * tan * dist;
    const pxToWorld = visibleH / h;
    const centerY =
      (contentTop + contentBottom) / 2 + ((this.insets.top - this.insets.bottom) / 2) * pxToWorld;

    this.camLook.set(0, centerY, 0);
    this.camBase.set(0, centerY + dist * 0.1, dist);
    this.camera.updateProjectionMatrix();

    // keep the moon fully on screen whatever the aspect ratio
    if (this.moon) {
      this.camera.position.copy(this.camBase);
      this.camera.lookAt(this.camLook);
      this.camera.updateMatrixWorld();
      const jarRight = new THREE.Vector3((W / 2 + WORLD.wall) * S, H * S, FRAME_DEPTH).project(
        this.camera,
      ).x;
      this.moon.place(this.camera, w, h, jarRight, this.skyBand());
    }
  }
}

// ======================================================================
// helpers

class Particles {
  private mesh: THREE.InstancedMesh;
  private n = 700;
  private pos: THREE.Vector3[] = [];
  private vel: THREE.Vector3[] = [];
  private life = new Float32Array(this.n);
  private maxLife = new Float32Array(this.n);
  private size = new Float32Array(this.n);
  private cursor = 0;
  private m = new THREE.Matrix4();
  private q = new THREE.Quaternion();
  private e = new THREE.Euler();
  private s = new THREE.Vector3();

  constructor(scene: THREE.Scene) {
    this.mesh = new THREE.InstancedMesh(
      new THREE.BoxGeometry(1, 1, 1),
      new THREE.MeshBasicMaterial({ toneMapped: false }),
      this.n,
    );
    this.mesh.frustumCulled = false;
    const white = new THREE.Color(1, 1, 1);
    for (let i = 0; i < this.n; i++) {
      this.pos.push(new THREE.Vector3());
      this.vel.push(new THREE.Vector3());
      this.mesh.setColorAt(i, white);
      this.mesh.setMatrixAt(i, new THREE.Matrix4().makeScale(0, 0, 0));
    }
    scene.add(this.mesh);
  }

  burst(at: THREE.Vector3, color: string, count: number, power: number) {
    const c = new THREE.Color(color);
    for (let k = 0; k < count; k++) {
      const i = this.cursor;
      this.cursor = (this.cursor + 1) % this.n;
      this.pos[i].copy(at);
      const a = Math.random() * Math.PI * 2;
      const sp = power * (0.4 + Math.random() * 0.6);
      this.vel[i].set(
        Math.cos(a) * sp,
        Math.sin(a) * sp + power * 0.4,
        (Math.random() - 0.2) * sp * 0.5,
      );
      this.maxLife[i] = this.life[i] = 0.5 + Math.random() * 0.5;
      this.size[i] = 0.05 + Math.random() * 0.09;
      this.mesh.setColorAt(i, c);
    }
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }

  update(dt: number) {
    for (let i = 0; i < this.n; i++) {
      if (this.life[i] <= 0) continue;
      this.life[i] -= dt;
      const v = this.vel[i];
      v.y -= 9 * dt;
      v.multiplyScalar(1 - dt * 1.5);
      this.pos[i].addScaledVector(v, dt);
      const k = Math.max(0, this.life[i] / this.maxLife[i]);
      this.e.set(this.life[i] * 7, this.life[i] * 5, 0);
      this.q.setFromEuler(this.e);
      this.s.setScalar(this.size[i] * k);
      this.m.compose(this.pos[i], this.q, this.s);
      this.mesh.setMatrixAt(i, this.m);
    }
    this.mesh.instanceMatrix.needsUpdate = true;
  }
}

class EmotePops {
  private tex = new Map<string, THREE.Texture>();
  private live: { sprite: THREE.Sprite; t: number; base: number }[] = [];

  constructor(private scene: THREE.Scene) {
    const loader = new THREE.TextureLoader();
    for (const n of ['heart', 'star', 'stars', 'cash']) {
      const t = loader.load(`./emotes/emote_${n}.png`);
      t.colorSpace = THREE.SRGBColorSpace;
      this.tex.set(n, t);
    }
  }

  pop(name: string, at: THREE.Vector3, scale: number) {
    const map = this.tex.get(name);
    if (!map) return;
    const sprite = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map,
        transparent: true,
        depthTest: false,
        toneMapped: false,
        fog: false,
      }),
    );
    sprite.position.copy(at);
    sprite.position.z = 1.2;
    sprite.renderOrder = 10;
    this.scene.add(sprite);
    this.live.push({ sprite, t: 0, base: scale });
  }

  update(dt: number) {
    for (const p of this.live) {
      p.t += dt;
      const k = p.t / 0.95;
      const grow = Math.min(1, p.t / 0.12);
      p.sprite.scale.setScalar(
        p.base * (0.4 + 0.6 * grow) * (1 + Math.sin(Math.min(1, k) * Math.PI) * 0.15),
      );
      p.sprite.position.y += dt * 0.9;
      p.sprite.material.opacity = k < 0.6 ? 1 : Math.max(0, 1 - (k - 0.6) / 0.4);
      if (k >= 1) {
        this.scene.remove(p.sprite);
        p.sprite.material.dispose();
      }
    }
    this.live = this.live.filter((p) => p.t / 0.95 < 1);
  }
}

/** rasterise an SVG string into a texture */
function svgTexture(svg: string, w = TEX_SIZE, h = w): Promise<THREE.Texture> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = w;
      canvas.height = h;
      canvas.getContext('2d')!.drawImage(img, 0, 0, w, h);
      const tex = new THREE.CanvasTexture(canvas);
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.anisotropy = 4;
      resolve(tex);
    };
    img.onerror = reject;
    img.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
  });
}

/** soft dark band at the bottom of the back panel */
function makeFadeTexture(): THREE.Texture {
  const c = document.createElement('canvas');
  c.width = 4;
  c.height = 64;
  const ctx = c.getContext('2d')!;
  const g = ctx.createLinearGradient(0, 0, 0, 64);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(0,0,0,0.55)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 4, 64);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function disposeTree(root: THREE.Object3D) {
  root.traverse((o) => {
    const m = o as THREE.Mesh;
    if (!m.isMesh && !(o as THREE.Sprite).isSprite) return;
    m.geometry?.dispose();
    const mats = Array.isArray(m.material) ? m.material : [m.material];
    for (const mat of mats) {
      if (!mat) continue;
      for (const v of Object.values(mat)) if (v instanceof THREE.Texture) v.dispose();
      mat.dispose();
    }
  });
}
