/** Bonus when two golden SNEK collide and blast off to the moon */
export const MOON_BONUS = 500;

/** Only the first few levels can be dropped. Weighted so small ones are common. */
const DROP_WEIGHTS = [30, 26, 20, 14, 10];
export function pickDropLevel(rand = Math.random): number {
  const total = DROP_WEIGHTS.reduce((a, b) => a + b, 0);
  let r = rand() * total;
  for (let i = 0; i < DROP_WEIGHTS.length; i++) {
    r -= DROP_WEIGHTS[i];
    if (r < 0) return i;
  }
  return 0;
}

