// Tiny synthesized sound effects (no audio files needed).
export class Sfx {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  muted = false;

  /** Must be called from a user gesture at least once (mobile autoplay rules). */
  unlock() {
    try {
      if (!this.ctx) {
        const AC =
          window.AudioContext ||
          (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
        this.ctx = new AC();
        this.master = this.ctx.createGain();
        this.master.gain.value = 0.5;
        this.master.connect(this.ctx.destination);
      }
      if (this.ctx.state === 'suspended') void this.ctx.resume();
    } catch {
      this.ctx = null;
    }
  }

  private tone(
    freq: number,
    dur: number,
    type: OscillatorType,
    vol: number,
    slideTo?: number,
    delay = 0,
  ) {
    if (this.muted || !this.ctx || !this.master) return;
    const t0 = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(slideTo, t0 + dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(vol, t0 + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g).connect(this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.02);
  }

  drop() {
    this.tone(320, 0.09, 'triangle', 0.18, 180);
  }

  thud(strength: number) {
    this.tone(110, 0.08, 'sine', Math.min(0.25, 0.05 + strength * 0.03), 70);
  }

  merge(level: number, combo: number) {
    const base = 300 * Math.pow(2, (level * 2 + Math.min(combo - 1, 6)) / 12);
    this.tone(base, 0.13, 'sine', 0.28, base * 1.5);
    this.tone(base * 1.5, 0.16, 'triangle', 0.12, base * 2, 0.05);
  }

  unlockNew() {
    [523, 659, 784, 1047].forEach((f, i) =>
      this.tone(f, 0.18, 'square', 0.07, undefined, i * 0.07),
    );
  }

  moon() {
    [392, 523, 659, 784, 1047, 1319].forEach((f, i) =>
      this.tone(f, 0.25, 'triangle', 0.16, f * 1.02, i * 0.08),
    );
    this.tone(80, 1.2, 'sawtooth', 0.06, 900, 0.1);
  }

  warn() {
    this.tone(880, 0.07, 'square', 0.06);
  }

  gameOver() {
    [523, 415, 330, 220].forEach((f, i) =>
      this.tone(f, 0.28, 'triangle', 0.18, f * 0.94, i * 0.16),
    );
  }

  /** filtered white noise burst (explosions, crackles, stamps) */
  private noise(
    dur: number,
    vol: number,
    type: BiquadFilterType,
    freq: number,
    delay = 0,
    freqTo?: number,
  ) {
    if (this.muted || !this.ctx || !this.master) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const len = Math.ceil(ctx.sampleRate * dur);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    const src = ctx.createBufferSource();
    src.buffer = buf;
    const f = ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(freq, t0);
    if (freqTo) f.frequency.exponentialRampToValueAtTime(freqTo, t0 + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(vol, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(f).connect(g).connect(this.master);
    src.start(t0);
    src.stop(t0 + dur + 0.02);
  }

  /** margin-call siren right before liquidation */
  siren() {
    for (let i = 0; i < 2; i++) {
      this.tone(560, 0.15, 'sawtooth', 0.08, 1100, i * 0.3);
      this.tone(1100, 0.15, 'sawtooth', 0.08, 560, i * 0.3 + 0.15);
    }
  }

  /** the jar bursts */
  boom() {
    this.noise(1.2, 0.8, 'lowpass', 2200, 0, 90);
    this.tone(95, 1.0, 'sine', 0.55, 28);
    this.noise(0.3, 0.25, 'highpass', 3000, 0.02);
    for (let i = 0; i < 6; i++)
      this.noise(0.05, 0.12, 'highpass', 3500, 0.25 + i * 0.07 + Math.random() * 0.04);
  }

  /** rubber stamp hitting the liquidation notice */
  stamp() {
    this.noise(0.14, 0.6, 'lowpass', 1100);
    this.tone(130, 0.16, 'sine', 0.4, 55);
  }

  /** victory fanfare */
  fanfare() {
    [523, 659, 784].forEach((f, i) => this.tone(f, 0.16, 'square', 0.08, undefined, i * 0.12));
    this.tone(1047, 0.5, 'square', 0.08, undefined, 0.36);
    [523, 659, 784, 1047].forEach((f) => this.tone(f, 1.1, 'triangle', 0.1, undefined, 0.62));
  }

  /** take-profit: cash register "ka-ching" + a happy arpeggio */
  cashOut() {
    this.noise(0.08, 0.35, 'highpass', 2500);
    this.tone(1568, 0.12, 'square', 0.08, undefined, 0.05);
    this.tone(2093, 0.35, 'square', 0.08, undefined, 0.13);
    [784, 988, 1175, 1568].forEach((f, i) =>
      this.tone(f, 0.2, 'triangle', 0.12, undefined, 0.45 + i * 0.09),
    );
  }

  firework() {
    this.noise(0.6, 0.22, 'bandpass', 2600, 0, 500);
    for (let i = 0; i < 5; i++)
      this.noise(0.04, 0.08, 'highpass', 4500, 0.18 + i * 0.06 + Math.random() * 0.05);
  }
}
